window.TURATH_TK(2,{"n49":{"a":["قال الله تعالى:","﴿وَمَا زَادَهُمْ إِلَّا إِيمَانًا وَتَسْلِيمًا﴾","[الأحزاب: ٢٢]","وقال جل ذكره:","﴿وَيَزْدَادَ الَّذِينَ آمَنُوا إِيمَانًا﴾","[المدثر: ٣١]","وقال تبارك وتعالى:","﴿فَأَمَّا الَّذِينَ آمَنُوا فَزَادَتْهُمْ إِيمَانًا﴾","[التوبة: ١٢٤]","وقال تعالى:","﴿فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا﴾","[آل عمران: ١٧٣]","وقال تعالى:","﴿لِيَزْدَادُوا إِيمَانًا مَعَ إِيمَانِهِمْ﴾","[الفتح: ٤]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“এতে তাদের ঈমান ও আত্মসমর্পণই কেবল বৃদ্ধি পেয়েছিল।”","[সূরা আল-আহযাব ৩৩:২২]","আর তিনি, যাঁর স্মরণ মহিমান্বিত, বলেছেন:","“যাতে যারা ঈমান এনেছে তাদের ঈমান বৃদ্ধি পায়।”","[সূরা আল-মুদ্দাসসির ৭৪:৩১]","আর তিনি, বরকতময় ও সর্বোচ্চ, বলেছেন:","“আর যারা ঈমান এনেছে, এটি তাদের ঈমান বৃদ্ধি করে।”","[সূরা আত-তাওবাহ ৯:১২৪]","আর তিনি বলেছেন:","“অতএব তাদের ভয় করো; আর তা তাদের ঈমান বৃদ্ধি করেছিল।”","[আলে ইমরান ৩:১৭৩]","আর তিনি বলেছেন:","“যাতে তারা তাদের ঈমানের সঙ্গে আরও ঈমান বৃদ্ধি করতে পারে।”","[সূরা আল-ফাতহ ৪৮:৪]"],"e":["Allah Most High said:","“And it only increased them in faith and submission.”","[Sūrat al-Aḥzāb 33:22]","And He, Glorified is His remembrance, said:","“So that those who believe may increase in faith.”","[Sūrat al-Muddaththir 74:31]","And He, Blessed and Exalted, said:","“As for those who believe, it increases them in faith.”","[Sūrat al-Tawbah 9:124]","And He said:","“So fear them; and it increased them in faith.”","[Āl ʿImrān 3:173]","And He said:","“So that they may increase in faith along with their faith.”","[Sūrat al-Fatḥ 48:4]"]},"n68":{"a":["قال الله تعالى:","﴿قَالَتِ الأَعْرَابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا وَلَكِنْ قُولُوا أَسْلَمْنَا﴾","[الحجرات: ١٤]","فإذا كان على الحقيقة، فهو على قوله جل ذكره:","﴿إِنَّ الدِّينَ عِنْدَ اللهِ الإِسْلَامُ﴾","[آل عمران: ١٩]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“বেদুইনরা বলে, ‘আমরা ঈমান এনেছি।’ বলুন: ‘তোমরা এখনও ঈমান আননি; বরং বলো, “আমরা আত্মসমর্পণ করেছি।”’”","[সূরা আল-হুজুরাত ৪৯:১৪]","কিন্তু ইসলাম যখন বাস্তবিক অর্থে সত্য ও প্রকৃত হয়, তখন তা তাঁর এই বাণীর সঙ্গে সামঞ্জস্যপূর্ণ—যাঁর স্মরণ মহিমান্বিত:","“নিশ্চয়ই আল্লাহর কাছে দীন হলো ইসলাম।”","[আলে ইমরান ৩:১৯]"],"e":["Allah Most High said:","“The Bedouins say, ‘We believe.’ Say: ‘You have not yet believed; rather say, “We have submitted.”’”","[Sūrat al-Ḥujurāt 49:14]","But when Islam is genuine in reality, then it accords with His statement, Glorified is His remembrance:","“Indeed, the religion in the sight of Allah is Islam.”","[Āl ʿImrān 3:19]"]},"n132":{"a":["قال الأوزاعي رحمه الله:","قال الله تعالى:","﴿لَتَدْخُلُنَّ الْمَسْجِدَ الْحَرَامَ إِنْ شَاءَ اللهُ آمِنِينَ﴾","[الفتح: ٢٧]","قال:","قد علم الله تعالى أنهم سيدخلون، وقد قال:","﴿إِنْ شَاءَ اللهُ﴾."],"b":["আল-আওযাঈ (রহিমাহুল্লাহ) বলেছেন:","আল্লাহ সর্বোচ্চ বলেছেন:","“আল্লাহ চাইলে তোমরা অবশ্যই নিরাপদ অবস্থায় আল-মাসজিদুল হারামে প্রবেশ করবে।”","[সূরা আল-ফাতহ ৪৮:২৭]","আল্লাহ আগে থেকেই জানতেন যে তারা সেখানে প্রবেশ করবে, তবুও তিনি বলেছেন:","“আল্লাহ চাইলে।”"],"e":["Al-Awzāʿī, may Allah have mercy on him, said:","Allah Most High said:","“You will surely enter al-Masjid al-Ḥarām, if Allah wills, in safety.”","[Sūrat al-Fatḥ 48:27]","Allah already knew that they would enter it, yet He nevertheless said:","“If Allah wills.”"]},"n207":{"a":["قال الله تعالى:","﴿وَإِذْ أَخَذَ رَبُّكَ مِنْ بَنِي آدَمَ مِنْ ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَى أَنْفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قَالُوا بَلَى شَهِدْنَا أَنْ تَقُولُوا يَوْمَ الْقِيَامَةِ إِنَّا كُنَّا عَنْ هَذَا غَافِلِينَ﴾","[الأعراف: ١٧٢]","ومعنى الآية:","وإذ أخذ ربك من بني آدم من ظهورهم ذريتهم، وأشهدهم على أنفسهم: ألست بربكم؟ قالوا: بلى.","فقال الله وملائكته: شهدنا عليكم بإقراركم بالله ربكم، كيلا تقولوا يوم القيامة: إنا كنا عن هذا غافلين.","انظر: تفسير الطبري (١٠/٥٦٤).","وقال إسحاق بن راهويه:","«أجمع أهل العلم أن الله خلق الأرواح قبل الأجساد، وأنه استنطقهم وأشهدهم».","أي: على ربوبيته.","وقال ابن الأنباري:","«مذهب أهل الحديث وكبراء أهل العلم في هذه الآية أن الله أخرج ذرية آدم من صلبه، وصلب أولاده، وهم في صور الذر، فأخذ عليهم الميثاق أنه خالقهم وأنهم مصنوعون، فاعترفوا بذلك وقبلوا»."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আর যখন আপনার রব আদমসন্তানের পিঠ থেকে তাদের বংশধরদের বের করলেন এবং তাদের নিজেদের বিরুদ্ধে সাক্ষ্য দিতে বললেন: ‘আমি কি তোমাদের রব নই?’ তারা বলল: ‘হ্যাঁ, আমরা সাক্ষ্য দিচ্ছি’—যাতে কিয়ামতের দিন তোমরা বলতে না পারো, ‘নিশ্চয়ই আমরা এ বিষয়ে অজ্ঞ ছিলাম।’”","[সূরা আল-আ‘রাফ ৭:১৭২]","আয়াতের অর্থ হলো:","আপনার রব আদমসন্তানের পিঠ থেকে তাদের বংশধরদের বের করলেন এবং তাদের নিজেদের বিরুদ্ধে সাক্ষ্য দিতে বললেন:","“আমি কি তোমাদের রব নই?”","তারা উত্তর দিল:","“হ্যাঁ।”","এরপর আল্লাহ ও তাঁর ফেরেশতাগণ তাদের এই স্বীকারোক্তির বিরুদ্ধে সাক্ষ্য দিলেন যে আল্লাহই তাদের রব, যাতে কিয়ামতের দিন তারা বলতে না পারে:","“আমরা এ বিষয়ে অজ্ঞ ছিলাম।”","দেখুন: তাফসীর আত-তাবারী (১০/৫৬৪)।","ইসহাক ইবন রাহাওয়াইহ বলেছেন:","“জ্ঞানীগণ একমত যে আল্লাহ দেহসমূহের পূর্বে রূহসমূহ সৃষ্টি করেছেন, তাদের কথা বলিয়েছেন এবং তাদের সাক্ষ্য গ্রহণ করেছেন।”","অর্থাৎ তিনি তাদের তাঁর রবুবিয়্যাত সম্পর্কে সাক্ষ্য দিতে বলেছেন।","ইবনুল আনবারী বলেছেন:","“এই আয়াত সম্পর্কে হাদীসের আলেম ও শীর্ষস্থানীয় আলেমদের অভিমত হলো—আল্লাহ আদমের পৃষ্ঠদেশ থেকে এবং তাঁর বংশধরদের পৃষ্ঠদেশ থেকে তাদের বংশধরদের ক্ষুদ্র কণার আকৃতিতে বের করেছিলেন। তিনি তাদের কাছ থেকে এই অঙ্গীকার নিয়েছিলেন যে তিনিই তাদের স্রষ্টা এবং তারা সৃষ্ট জীব। তারা তা স্বীকার ও গ্রহণ করেছিল।”"],"e":["Allah Most High said:","“And when your Lord brought forth from the children of Adam, from their backs, their descendants and made them testify concerning themselves: ‘Am I not your Lord?’ They said: ‘Yes, we testify,’ lest you should say on the Day of Resurrection, ‘Indeed, we were unaware of this.’”","[Sūrat al-Aʿrāf 7:172]","The meaning of the verse is:","Your Lord brought forth from the children of Adam, from their backs, their descendants and made them testify concerning themselves:","“Am I not your Lord?”","They replied:","“Yes.”","Allah and His angels then bore witness against them concerning their acknowledgment that Allah is their Lord, so that they could not say on the Day of Resurrection:","“We were unaware of this.”","See Tafsīr al-Ṭabarī (10/564).","Isḥāq ibn Rāhawayh said:","“The people of knowledge are agreed that Allah created the souls before the bodies, caused them to speak, and made them testify.”","That is, He made them testify concerning His Lordship.","Ibn al-Anbārī said:","“The position of the scholars of ḥadīth and the leading scholars concerning this verse is that Allah brought forth the descendants of Adam from his loins and from the loins of his descendants while they were in the form of tiny particles. He took from them the covenant that He was their Creator and that they were created beings. They acknowledged this and accepted it.”"]},"n212":{"a":["قال الله تعالى:","﴿وَإِمَّا يَنْزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللهِ﴾","[الأعراف: ٢٠٠؛ فصلت: ٣٦]","والنزغ والهمز: الوسوسة.","وقوله سبحانه حاكياً عن يوسف عليه السلام:","﴿مِنْ بَعْدِ أَنْ نَزَغَ الشَّيْطَانُ بَيْنِي وَبَيْنَ إِخْوَتِي﴾","[يوسف: ١٠٠]","أي: أفسد وأغرى.","وقوله تعالى:","﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ﴾","[الناس: ١–٦]","والخناس هو الشيطان؛ يوسوس في صدر المرء، فإذا ذكر الله خنس، أي: انقبض وتأخر."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“যদি শয়তানের পক্ষ থেকে কোনো কুমন্ত্রণা তোমাকে প্ররোচিত করে, তবে আল্লাহর আশ্রয় চাও।”","[সূরা আল-আ‘রাফ ৭:২০০; সূরা ফুসসিলাত ৪১:৩৬]","আন-নাযগ ও আল-হাময শব্দদ্বয় ওয়াসওয়াসা ও প্ররোচনাকে বোঝায়।","আল্লাহ, যিনি মহিমান্বিত, ইউসুফ (আলাইহিস সালাম)-এর বক্তব্য বর্ণনা করতে গিয়ে বলেছেন:","“শয়তান আমার ও আমার ভাইদের মধ্যে বিবাদ সৃষ্টি করার পর।”","[সূরা ইউসুফ ১২:১০০]","অর্থাৎ শয়তান তাদের মধ্যকার সম্পর্ক নষ্ট করেছিল এবং তাদের উসকে দিয়েছিল।","আল্লাহ সর্বোচ্চ আরও বলেছেন:","“বলুন: আমি আশ্রয় চাই মানুষের রবের কাছে, মানুষের অধিপতির কাছে, মানুষের ইলাহের কাছে—পিছু হটা কুমন্ত্রণাদাতার অনিষ্ট থেকে, যে মানুষের অন্তরে কুমন্ত্রণা দেয়—জিন ও মানুষের মধ্য থেকে।”","[সূরা আন-নাস ১১৪:১–৬]","আল-খান্নাস হলো শয়তান। সে মানুষের অন্তরে ওয়াসওয়াসা দেয়; কিন্তু আল্লাহকে স্মরণ করা হলে সে পিছিয়ে যায়—অর্থাৎ সরে যায় ও পিছু হটে।"],"e":["Allah Most High said:","“If a prompting from Satan provokes you, then seek refuge in Allah.”","[Sūrat al-Aʿrāf 7:200; Sūrat Fuṣṣilat 41:36]","The words al-nazgh and al-hamz refer to whispering and prompting.","Allah, Glorified is He, said while relating the words of Yūsuf, peace be upon him:","“After Satan had stirred up discord between me and my brothers.”","[Sūrat Yūsuf 12:100]","That is, Satan corrupted matters between them and incited them.","Allah Most High also said:","“Say: I seek refuge in the Lord of mankind, the King of mankind, the God of mankind, from the evil of the whisperer who withdraws, who whispers into the breasts of mankind, from among jinn and mankind.”","[Sūrat al-Nās 114:1–6]","Al-khannās is Satan. He whispers into a person’s chest, but when Allah is remembered he withdraws — that is, he recoils and retreats."]},"n222":{"a":["قال الله تعالى:","﴿وَاعْبُدُوا اللهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا﴾","[النساء: ٣٦]","وقال تعالى:","﴿يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ﴾","[البقرة: ٢١]","وقال تعالى:","﴿وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ﴾","[الذاريات: ٥٦]","وغيرها من الآيات، وهي كثيرة في كتاب الله؛ لأن دعوة الأنبياء عليهم السلام كانت لتوحيد الإلهية.","قال شيخ الإسلام ابن تيمية رحمه الله تعالى:","«إن عامة المتكلمين الذين يقررون التوحيد في كتب الكلام والنظر، غايتهم أن يجعلوا التوحيد ثلاثة أنواع، فيقولون: هو واحد في ذاته لا قسيم له، وواحد في صفاته لا شبيه له، وواحد في أفعاله لا شريك له.","وأشهر الأنواع الثلاثة عندهم هو الثالث، وهو توحيد الأفعال، وهو أن خالق العالم واحد. وهم يحتجون على ذلك بما يذكرونه من دلالة التمانع وغيرها، ويظنون أن هذا هو التوحيد المطلوب، وأن هذا هو معنى قولنا: لا إله إلا الله، حتى يجعلوا معنى الإلهية القدرة على الاختراع.","ومعلوم أن المشركين من العرب الذين بُعث إليهم محمد ﷺ أولاً لم يكونوا يخالفونه في هذا، بل كانوا يقرون بأن الله خالق كل شيء، حتى إنهم كانوا يقرون بالقدر أيضاً، وهم مع هذا مشركون».","مجموع الفتاوى (٣/٩٨)."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আল্লাহর ইবাদত করো এবং তাঁর সঙ্গে কোনো কিছুকে শরিক করো না।”","[সূরা আন-নিসা ৪:৩৬]","আর তিনি বলেছেন:","“হে মানবজাতি, তোমাদের রবের ইবাদত করো, যিনি তোমাদের এবং তোমাদের পূর্ববর্তীদের সৃষ্টি করেছেন, যাতে তোমরা তাকওয়া অবলম্বন করতে পারো।”","[সূরা আল-বাকারা ২:২১]","আর তিনি বলেছেন:","“আমি জিন ও মানুষকে কেবল আমার ইবাদতের জন্যই সৃষ্টি করেছি।”","[সূরা আয-যারিয়াত ৫১:৫৬]","আল্লাহর কিতাবে এ ধরনের আরও বহু আয়াত রয়েছে; কারণ নবীগণের (আলাইহিমুস সালাম) দাওয়াত ছিল ইবাদতে একত্বের দিকে।","শাইখুল ইসলাম ইবন তাইমিয়্যাহ (রহিমাহুল্লাহ) বলেছেন:","“কালামশাস্ত্র ও বুদ্ধিবৃত্তিক অনুসন্ধানের গ্রন্থে যেসব কালামবিদ তাওহীদ প্রতিষ্ঠা করেন, তাদের অধিকাংশ শেষ পর্যন্ত তা তিন প্রকারে বিভক্ত করেন। তারা বলে: তিনি তাঁর সত্তায় এক—তাঁর কোনো বিভাজন বা সমকক্ষ নেই; তাঁর গুণাবলিতে এক—তাঁর কোনো সদৃশ নেই; এবং তাঁর কর্মে এক—তাঁর কোনো অংশীদার নেই।","তাদের কাছে এই তিনটির মধ্যে সবচেয়ে পরিচিত হলো তৃতীয়টি: কর্মে একত্ব—অর্থাৎ বিশ্বজগতের স্রষ্টা একজন। তারা এ বিষয়ে তাদের কথিত ‘পারস্পরিক বাধা’র প্রমাণ ও অনুরূপ যুক্তি পেশ করে। তারা মনে করে এটাই প্রত্যাশিত তাওহীদ এবং ‘আল্লাহ ছাড়া কোনো সত্য উপাস্য নেই’—আমাদের এই কথার অর্থও এটাই; এমনকি তারা ইলাহিয়্যাতকে কেবল সৃষ্টি ও উদ্ভব ঘটানোর ক্ষমতা হিসেবে ব্যাখ্যা করে।","অথচ সুপরিচিত বিষয় হলো—মুহাম্মাদ ﷺ যেসব আরব মুশরিকের কাছে প্রথমে প্রেরিত হয়েছিলেন, তারা এ বিষয়ে বিরোধিতা করত না। বরং তারা স্বীকার করত যে আল্লাহই সবকিছুর স্রষ্টা। এমনকি তারা তাকদীরও স্বীকার করত; তবুও তারা মুশরিকই ছিল।”","মাজমূ‘ আল-ফাতাওয়া (৩/৯৮)।"],"e":["Allah Most High said:","“Worship Allah and do not associate anything with Him.”","[Sūrat al-Nisāʾ 4:36]","And He said:","“O mankind, worship your Lord who created you and those before you, so that you may become mindful of Him.”","[Sūrat al-Baqarah 2:21]","And He said:","“I did not create the jinn and mankind except to worship Me.”","[Sūrat al-Dhāriyāt 51:56]","Shaykh al-Islām Ibn Taymiyyah, may Allah have mercy on him, said:","“Most of the theologians who establish tawḥīd in works of speculative theology and rational inquiry ultimately divide it into three types. They say: He is One in His essence with no division or counterpart; One in His attributes with no likeness; and One in His actions with no partner.","The best known of these three types among them is the third: oneness in actions, meaning that the Creator of the universe is One. They argue for this through what they call the proof of mutual hindrance and similar arguments. They imagine that this is the tawḥīd being sought and that this is the meaning of our statement, ‘There is no deity worthy of worship except Allah,’ until they interpret divinity as merely the power to create and originate.","Yet it is well known that the Arab polytheists to whom Muḥammad ﷺ was initially sent did not dispute this point. Rather, they acknowledged that Allah is the Creator of everything. They even acknowledged divine decree, yet despite this they remained polytheists.”","Majmūʿ al-Fatāwā (3/98)."]},"n227":{"a":["قال الله تعالى:","﴿فَلَا تَجْعَلُوا لِلَّهِ أَنْدَادًا وَأَنْتُمْ تَعْلَمُونَ﴾","[البقرة: ٢٢]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“সুতরাং জেনেশুনে আল্লাহর সমকক্ষ স্থির করো না।”","[সূরা আল-বাকারা ২:২২]"],"e":["Allah Most High said:","“So do not set up rivals to Allah while you know.”","[Sūrat al-Baqarah 2:22]"]},"n242":{"a":["قال الله تعالى:","﴿وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا وَذَرُوا الَّذِينَ يُلْحِدُونَ فِي أَسْمَائِهِ سَيُجْزَوْنَ مَا كَانُوا يَعْمَلُونَ﴾","[الأعراف: ١٨٠]","وقال تعالى:","﴿قُلِ ادْعُوا اللهَ أَوِ ادْعُوا الرَّحْمَنَ أَيًّا مَا تَدْعُوا فَلَهُ الْأَسْمَاءُ الْحُسْنَى﴾","[الإسراء: ١١٠]","وقوله:","﴿فَادْعُوهُ بِهَا﴾","والدعاء هو العبادة."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আল্লাহরই সুন্দরতম নামসমূহ। অতএব তাঁকে সেসব নাম ধরে ডাকো এবং যারা তাঁর নামসমূহের ব্যাপারে বক্রতা অবলম্বন করে তাদের ছেড়ে দাও। তারা যা করত তার প্রতিফল তাদের দেওয়া হবে।”","[সূরা আল-আ‘রাফ ৭:১৮০]","আর তিনি বলেছেন:","“বলুন: তোমরা ‘আল্লাহ’ বলে ডাকো অথবা ‘আর-রহমান’ বলে ডাকো—যে নামেই ডাকো না কেন, সুন্দরতম নামসমূহ তাঁরই।”","[সূরা আল-ইসরা ১৭:১১০]","তাঁর বাণী:","“অতএব তাঁকে সেসব নাম ধরে ডাকো”","দু‘আর নির্দেশ করে, আর দু‘আ হলো ইবাদত।"],"e":["Allah Most High said:","“To Allah belong the Most Beautiful Names, so call upon Him by them and leave those who deviate concerning His Names. They will be recompensed for what they used to do.”","[Sūrat al-Aʿrāf 7:180]","And He said:","“Say: Call upon Allah or call upon the Most Merciful. Whichever you call upon, to Him belong the Most Beautiful Names.”","[Sūrat al-Isrāʾ 17:110]","His statement:","“So call upon Him by them”","indicates supplication, and supplication is worship."]},"n248":{"a":["قال الله تعالى:","﴿اللهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ﴾","[البقرة: ٢٥٥]","وقال تعالى:","﴿وَتَوَكَّلْ عَلَى الْحَيِّ الَّذِي لَا يَمُوتُ﴾","[الفرقان: ٥٨]","وقال تعالى:","﴿وَعَنَتِ الْوُجُوهُ لِلْحَيِّ الْقَيُّومِ﴾","[طه: ١١١]","والآيات في هذا المعنى كثيرة."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আল্লাহ—তিনি ছাড়া কোনো সত্য উপাস্য নেই; তিনি চিরঞ্জীব, সবকিছুর ধারক ও রক্ষণাবেক্ষণকারী।”","[সূরা আল-বাকারা ২:২৫৫]","আর তিনি বলেছেন:","“আর সেই চিরঞ্জীবের ওপর ভরসা করো, যিনি কখনো মৃত্যুবরণ করেন না।”","[সূরা আল-ফুরকান ২৫:৫৮]","আর তিনি বলেছেন:","“সব মুখ চিরঞ্জীব, সবকিছুর ধারক ও রক্ষণাবেক্ষণকারীর সামনে নত হবে।”","[সূরা ত্ব-হা ২০:১১১]","এই অর্থবাহী আরও বহু আয়াত রয়েছে।"],"e":["Allah Most High said:","“Allah — there is no deity worthy of worship except Him, the Ever-Living, the Sustainer of all.”","[Sūrat al-Baqarah 2:255]","And He said:","“Place your trust in the Ever-Living who does not die.”","[Sūrat al-Furqān 25:58]","And He said:","“All faces will be humbled before the Ever-Living, the Sustainer.”","[Sūrat Ṭā Hā 20:111]","There are many verses carrying this meaning."]},"n250":{"a":["قال الله تعالى فيما يقوله حملة العرش:","﴿رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَحْمَةً وَعِلْمًا﴾","[غافر: ٧]","وقال الله تعالى:","﴿إِنَّ اللهَ عِنْدَهُ عِلْمُ السَّاعَةِ﴾","[لقمان: ٣٤]","وقال تعالى:","﴿إِنَّمَا الْعِلْمُ عِنْدَ اللهِ﴾","[الملك: ٢٦]","وقال تعالى:","﴿وَأَضَلَّهُ اللهُ عَلَى عِلْمٍ﴾","[الجاثية: ٢٣]","قال مالك رحمه الله تعالى:","«الله في السماء، وعلمه في كل مكان، لا يخلو منه شيء».","السنة لعبد الله بن أحمد (ص ٥٣٢)."],"b":["আল্লাহ সর্বোচ্চ আরশ বহনকারী ফেরেশতাদের বক্তব্য সম্পর্কে বলেছেন:","“হে আমাদের রব, আপনি রহমত ও জ্ঞানে সবকিছুকে পরিব্যাপ্ত করে রেখেছেন।”","[সূরা গাফির ৪০:৭]","আর আল্লাহ সর্বোচ্চ বলেছেন:","“নিশ্চয়ই কিয়ামতের জ্ঞান একমাত্র আল্লাহর কাছেই রয়েছে।”","[সূরা লুকমান ৩১:৩৪]","আর তিনি বলেছেন:","“জ্ঞান তো কেবল আল্লাহর কাছেই।”","[সূরা আল-মুলক ৬৭:২৬]","আর তিনি বলেছেন:","“আল্লাহ তাকে জেনেশুনে পথভ্রষ্ট করেছেন।”","[সূরা আল-জাসিয়াহ ৪৫:২৩]","মালিক (রহিমাহুল্লাহ) বলেছেন:","“আল্লাহ আসমানের ঊর্ধ্বে, আর তাঁর জ্ঞান সর্বত্র; কোনো কিছুই এর বাইরে নয়।”","আস-সুন্নাহ, আবদুল্লাহ ইবন আহমাদ, পৃ. ৫৩২।"],"e":["Allah Most High said concerning the words of the bearers of the Throne:","“Our Lord, You encompass all things in mercy and knowledge.”","[Sūrat Ghāfir 40:7]","And Allah Most High said:","“Indeed, Allah alone has knowledge of the Hour.”","[Sūrat Luqmān 31:34]","And He said:","“Knowledge is only with Allah.”","[Sūrat al-Mulk 67:26]","And He said:","“Allah led him astray upon knowledge.”","[Sūrat al-Jāthiyah 45:23]","“Allah is above in the heaven, and His knowledge is everywhere; nothing is beyond it.”","Al-Sunnah by ʿAbdullāh ibn Aḥmad, p. 532."]},"n254":{"a":["قال الله تعالى:","﴿تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾","[الملك: ١]","وقال تعالى:","﴿قُلْ هُوَ الْقَادِرُ عَلَى أَنْ يَبْعَثَ عَلَيْكُمْ عَذَابًا مِنْ فَوْقِكُمْ أَوْ مِنْ تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُمْ بَأْسَ بَعْضٍ﴾","[الأنعام: ٦٥]","وقال تعالى:","﴿بَلَى قَادِرِينَ عَلَى أَنْ نُسَوِّيَ بَنَانَهُ﴾","[القيامة: ٤]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“বরকতময় তিনি, যাঁর হাতে রাজত্ব, এবং তিনি সবকিছুর ওপর ক্ষমতাবান।”","[সূরা আল-মুলক ৬৭:১]","আর তিনি বলেছেন:","“বলুন: তিনি তোমাদের ওপর থেকে অথবা তোমাদের পায়ের নিচ থেকে শাস্তি পাঠাতে সক্ষম, অথবা তোমাদের বিভিন্ন দলে বিভক্ত করতে এবং একদলকে অন্যদলের সহিংসতার স্বাদ আস্বাদন করাতে সক্ষম।”","[সূরা আল-আন‘আম ৬:৬৫]","আর তিনি বলেছেন:","“হ্যাঁ, অবশ্যই; আমি তো তার আঙুলের ডগাও পুনর্গঠন করতে পূর্ণ সক্ষম।”","[সূরা আল-কিয়ামাহ ৭৫:৪]"],"e":["Allah Most High said:","“Blessed is He in whose Hand is dominion, and He has power over all things.”","[Sūrat al-Mulk 67:1]","And He said:","“Say: He is able to send upon you punishment from above you or from beneath your feet, or to divide you into factions and make some of you taste the violence of others.”","[Sūrat al-Anʿām 6:65]","And He said:","“Yes indeed; We are fully able even to restore his fingertips.”","[Sūrat al-Qiyāmah 75:4]"]},"n257":{"a":["قال الله تعالى:","﴿وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾","[البقرة: ٢٥٥]","وقال تعالى:","﴿يُدَبِّرُ الْأَمْرَ مِنَ السَّمَاءِ إِلَى الْأَرْضِ ثُمَّ يَعْرُجُ إِلَيْهِ﴾","[السجدة: ٥]","وقال تعالى:","﴿تَعْرُجُ الْمَلَائِكَةُ وَالرُّوحُ إِلَيْهِ﴾","[المعارج: ٤]","وقال تعالى:","﴿يَخَافُونَ رَبَّهُمْ مِنْ فَوْقِهِمْ﴾","[النحل: ٥٠]","وقال تعالى:","﴿أَأَمِنْتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الْأَرْضَ﴾","[الملك: ١٦]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আর তিনি সর্বোচ্চ, মহান।”","[সূরা আল-বাকারা ২:২৫৫]","আর তিনি বলেছেন:","“তিনি আসমান থেকে পৃথিবী পর্যন্ত সব বিষয় পরিচালনা করেন; তারপর তা তাঁর দিকে আরোহণ করে।”","[সূরা আস-সাজদাহ ৩২:৫]","আর তিনি বলেছেন:","“ফেরেশতাগণ ও রূহ তাঁর দিকে আরোহণ করে।”","[সূরা আল-মা‘আরিজ ৭০:৪]","আর তিনি বলেছেন:","“তারা তাদের ওপরের রবকে ভয় করে।”","[সূরা আন-নাহল ১৬:৫০]","আর তিনি বলেছেন:","“তোমরা কি আসমানের ওপর যিনি আছেন তাঁর ব্যাপারে নিরাপদ হয়ে গেছ যে তিনি তোমাদেরসহ জমিন ধসিয়ে দেবেন না?”","[সূরা আল-মুলক ৬৭:১৬]"],"e":["Allah Most High said:","“And He is the Most High, the Most Great.”","[Sūrat al-Baqarah 2:255]","And He said:","“He directs the affair from the heaven to the earth; then it ascends to Him.”","[Sūrat al-Sajdah 32:5]","And He said:","“The angels and the Spirit ascend to Him.”","[Sūrat al-Maʿārij 70:4]","And He said:","“They fear their Lord above them.”","[Sūrat al-Naḥl 16:50]","And He said:","“Do you feel secure from the One who is in the heaven that He will not cause the earth to swallow you?”","[Sūrat al-Mulk 67:16]"]},"n281":{"a":["قال الله تعالى:","﴿الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى﴾","[طه: ٥]","وقال تعالى:","﴿ثُمَّ اسْتَوَى عَلَى الْعَرْشِ﴾","[الأعراف: ٥٤؛ يونس: ٣؛ الرعد: ٢؛ الفرقان: ٥٩؛ السجدة: ٤؛ الحديد: ٤]","ومعنى قوله:","﴿اسْتَوَى عَلَى الْعَرْشِ﴾","علا على العرش.","قال ابن عباس رضي الله عنهما:","«الكرسي موضع القدمين، والعرش لا يقدر أحد قدره».","رواه الحاكم (٢/٢٨٢)، وصححه وقال: على شرط الشيخين."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আর-রহমান আরশের ওপর ইস্তিওয়া করেছেন।”","[সূরা ত্ব-হা ২০:৫]","আর তিনি বলেছেন:","“তারপর তিনি আরশের ওপর ইস্তিওয়া করেছেন।”","[সূরা আল-আ‘রাফ ৭:৫৪; ইউনুস ১০:৩; আর-রা‘দ ১৩:২; আল-ফুরকান ২৫:৫৯; আস-সাজদাহ ৩২:৪; আল-হাদীদ ৫৭:৪]","তাঁর বাণী:","“আরশের ওপর ইস্তিওয়া করেছেন”","এর অর্থ: তিনি আরশের ঊর্ধ্বে উঠেছেন।","ইবন আব্বাস (রাদিয়াল্লাহু আনহুমা) বলেছেন:","“কুরসী হলো দুই পা রাখার স্থান; আর আরশের বিশালতা কেউ পরিমাপ করতে পারে না।”","আল-হাকিম (২/২৮২) এটি বর্ণনা করেছেন এবং সহীহ বলেছেন; তিনি বলেন, এটি আল-বুখারী ও মুসলিমের শর্ত অনুযায়ী।"],"e":["Allah Most High said:","“The Most Merciful rose over the Throne.”","[Sūrat Ṭā Hā 20:5]","And He said:","“Then He rose over the Throne.”","[Sūrat al-Aʿrāf 7:54; Yūnus 10:3; al-Raʿd 13:2; al-Furqān 25:59; al-Sajdah 32:4; al-Ḥadīd 57:4]","The meaning of His statement:","“Rose over the Throne”","is: He rose above the Throne.","“The Kursī is the place of the Feet, and no one can estimate the magnitude of the Throne.”","Narrated by al-Ḥākim (2/282), who authenticated it and said that it meets the conditions of al-Bukhārī and Muslim."]},"n308":{"a":["قال الله تعالى:","﴿وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ﴾","[الرحمن: ٢٧]","وقال تعالى:","﴿كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ﴾","[القصص: ٨٨]","وقال تعالى:","﴿وَمَا آتَيْتُمْ مِنْ زَكَاةٍ تُرِيدُونَ وَجْهَ اللهِ﴾","[الروم: ٣٩]","وقال تعالى:","﴿إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ اللهِ﴾","[الإنسان: ٩]","وقال تعالى:","﴿وَالَّذِينَ صَبَرُوا ابْتِغَاءَ وَجْهِ رَبِّهِمْ﴾","[الرعد: ٢٢]","وقال تعالى:","﴿يُرِيدُونَ وَجْهَهُ﴾","[الكهف: ٢٨]","وقال تعالى:","﴿إِلَّا ابْتِغَاءَ وَجْهِ رَبِّهِ الْأَعْلَى﴾","[الليل: ٢٠]","وغيرها من الآيات البينات."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আর আপনার রবের মুখমণ্ডল—মহিমা ও সম্মানের অধিকারী—অবশিষ্ট থাকবে।”","[সূরা আর-রহমান ৫৫:২৭]","আর তিনি বলেছেন:","“তাঁর মুখমণ্ডল ছাড়া সবকিছু ধ্বংসশীল।”","[সূরা আল-কাসাস ২৮:৮৮]","আর তিনি বলেছেন:","“আর তোমরা যাকাত হিসেবে যা দাও, আল্লাহর মুখমণ্ডল কামনা করে…”","[সূরা আর-রূম ৩০:৩৯]","আর তিনি বলেছেন:","“আমরা তোমাদের কেবল আল্লাহর মুখমণ্ডলের জন্যই আহার করাই।”","[সূরা আল-ইনসান ৭৬:৯]","আর তিনি বলেছেন:","“আর যারা তাদের রবের মুখমণ্ডল কামনা করে ধৈর্য ধারণ করে…”","[সূরা আর-রা‘দ ১৩:২২]","আর তিনি বলেছেন:","“তারা তাঁর মুখমণ্ডল কামনা করে।”","[সূরা আল-কাহফ ১৮:২৮]","আর তিনি বলেছেন:","“কেবল তার সর্বোচ্চ রবের মুখমণ্ডল কামনা করে।”","[সূরা আল-লাইল ৯২:২০]","এ বিষয়ে আরও অন্যান্য সুস্পষ্ট আয়াত রয়েছে।"],"e":["Allah Most High said:","“And the Face of your Lord, Possessor of Majesty and Honor, will remain.”","[Sūrat al-Raḥmān 55:27]","And He said:","“Everything will perish except His Face.”","[Sūrat al-Qaṣaṣ 28:88]","And He said:","“And whatever you give in zakāh, seeking the Face of Allah…”","[Sūrat al-Rūm 30:39]","And He said:","“We feed you only for the Face of Allah.”","[Sūrat al-Insān 76:9]","And He said:","“And those who remain patient, seeking the Face of their Lord…”","[Sūrat al-Raʿd 13:22]","And He said:","“They seek His Face.”","[Sūrat al-Kahf 18:28]","And He said:","“Except seeking the Face of his Lord, the Most High.”","[Sūrat al-Layl 92:20]","And there are other clear verses concerning this."]},"n328":{"a":["قال الله تعالى:","﴿لَقَدْ سَمِعَ اللهُ قَوْلَ الَّذِينَ قَالُوا إِنَّ اللهَ فَقِيرٌ وَنَحْنُ أَغْنِيَاءُ﴾","[آل عمران: ١٨١]","وقال الله عز وجل في قصة المجادلة:","﴿قَدْ سَمِعَ اللهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللهِ وَاللهُ يَسْمَعُ تَحَاوُرَكُمَا إِنَّ اللهَ سَمِيعٌ بَصِيرٌ﴾","[المجادلة: ١]","وقال تعالى مخاطباً موسى وهارون عليهما السلام:","﴿قَالَ لَا تَخَافَا إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَى﴾","[طه: ٤٦]","وقال تعالى:","﴿قَالَ كَلَّا فَاذْهَبَا بِآيَاتِنَا إِنَّا مَعَكُمْ مُسْتَمِعُونَ﴾","[الشعراء: ١٥]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আল্লাহ অবশ্যই তাদের কথা শুনেছেন যারা বলেছিল, ‘আল্লাহ দরিদ্র আর আমরা ধনী।’”","[আলে ইমরান ৩:১৮১]","আর আল্লাহ মহাপরাক্রমশালী ও মহিমান্বিত সেই নারীর ব্যাপারে বলেছেন যিনি বিতর্ক করেছিলেন:","“আল্লাহ অবশ্যই সেই নারীর কথা শুনেছেন, যে তার স্বামীর ব্যাপারে আপনার সঙ্গে বিতর্ক করে এবং আল্লাহর কাছে অভিযোগ করে। আল্লাহ তোমাদের কথোপকথন শুনছেন। নিশ্চয়ই আল্লাহ সর্বশ্রোতা, সর্বদ্রষ্টা।”","[সূরা আল-মুজাদিলাহ ৫৮:১]","আর তিনি মূসা ও হারূন (আলাইহিমাস সালাম)-কে সম্বোধন করে বলেছেন:","“ভয় করো না। নিশ্চয়ই আমি তোমাদের উভয়ের সঙ্গে আছি; আমি শুনি এবং দেখি।”","[সূরা ত্ব-হা ২০:৪৬]","আর তিনি বলেছেন:","“কখনোই নয়। তোমরা উভয়ে আমার নিদর্শনসমূহ নিয়ে যাও। নিশ্চয়ই আমি তোমাদের সঙ্গে আছি, শুনছি।”","[সূরা আশ-শু‘আরা ২৬:১৫]"],"e":["Allah Most High said:","“Allah has certainly heard the statement of those who said, ‘Indeed, Allah is poor while we are rich.’”","[Āl ʿImrān 3:181]","And Allah, Mighty and Majestic, said concerning the woman who disputed:","“Allah has certainly heard the statement of the woman who disputes with you concerning her husband and complains to Allah. Allah hears your conversation. Indeed, Allah is All-Hearing, All-Seeing.”","[Sūrat al-Mujādilah 58:1]","And He said, addressing Moses and Aaron peace be upon them:","“Do not fear. Indeed, I am with you both; I hear and I see.”","[Sūrat Ṭā Hā 20:46]","And He said:","“No. Go, both of you, with Our signs. Indeed, We are with you, listening.”","[Sūrat al-Shuʿarāʾ 26:15]"]},"n333":{"a":["قال الله تعالى:","﴿وَقَالَتِ الْيَهُودُ يَدُ اللهِ مَغْلُولَةٌ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا بِمَا قَالُوا بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنْفِقُ كَيْفَ يَشَاءُ﴾","[المائدة: ٦٤]","وقال تعالى:","﴿مَا مَنَعَكَ أَنْ تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ﴾","[ص: ٧٥]","وقال تعالى:","﴿فَسُبْحَانَ الَّذِي بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ وَإِلَيْهِ تُرْجَعُونَ﴾","[يس: ٨٣]","وقال تعالى:","﴿وَتُعِزُّ مَنْ تَشَاءُ وَتُذِلُّ مَنْ تَشَاءُ بِيَدِكَ الْخَيْرُ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾","[آل عمران: ٢٦]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“ইহুদিরা বলে, ‘আল্লাহর হাত বাঁধা।’ বরং তাদেরই হাত বাঁধা এবং তারা যা বলেছে তার কারণে তারা অভিশপ্ত। বরং তাঁর উভয় হাতই প্রসারিত; তিনি যেভাবে চান ব্যয় করেন।”","[সূরা আল-মায়িদাহ ৫:৬৪]","আর তিনি বলেছেন:","“আমি যাকে আমার দুই হাতে সৃষ্টি করেছি, তাকে সিজদা করতে তোমাকে কী বাধা দিল?”","[সূরা সাদ ৩৮:৭৫]","আর তিনি বলেছেন:","“অতএব মহিমান্বিত তিনি, যাঁর হাতে সবকিছুর রাজত্ব, এবং তাঁর দিকেই তোমাদের ফিরিয়ে নেওয়া হবে।”","[সূরা ইয়াসীন ৩৬:৮৩]","আর তিনি বলেছেন:","“আপনি যাকে ইচ্ছা সম্মানিত করেন এবং যাকে ইচ্ছা অপমানিত করেন। সকল কল্যাণ আপনার হাতে। নিশ্চয়ই আপনি সবকিছুর ওপর ক্ষমতাবান।”","[আলে ইমরান ৩:২৬]"],"e":["Allah Most High said:","“The Jews say, ‘Allah’s Hand is chained.’ Chained are their hands, and cursed are they for what they say. Rather, both His Hands are outstretched; He spends however He wills.”","[Sūrat al-Māʾidah 5:64]","And He said:","“What prevented you from prostrating to that which I created with My two Hands?”","[Sūrat Ṣād 38:75]","And He said:","“So glory be to the One in whose Hand is the dominion of all things, and to Him you will be returned.”","[Sūrat Yā Sīn 36:83]","And He said:","“You honor whom You will and humiliate whom You will. In Your Hand is all good. Indeed, You have power over all things.”","[Āl ʿImrān 3:26]"]},"n338":{"a":["قال الله تعالى:","﴿وَمَا قَدَرُوا اللهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ﴾","[الزمر: ٦٧]","وقال مجاهد:","«وكلتا يدي الرحمن يمين»."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“তারা আল্লাহকে তাঁর যথাযথ মর্যাদায় মূল্যায়ন করেনি। কিয়ামতের দিন সমগ্র পৃথিবী তাঁর মুঠোয় থাকবে এবং আসমানসমূহ তাঁর ডান হাতে গুটানো থাকবে। তারা যাদের শরিক করে তিনি তা থেকে পবিত্র ও বহু ঊর্ধ্বে।”","[সূরা আয-যুমার ৩৯:৬৭]","মুজাহিদ বলেছেন:","“আর-রহমানের উভয় হাতই ডান।”"],"e":["Allah Most High said:","“They did not appraise Allah with the appraisal due to Him. The earth altogether will be in His grasp on the Day of Resurrection, and the heavens will be folded in His Right Hand. Glorified and Exalted is He above what they associate with Him.”","[Sūrat al-Zumar 39:67]","Mujāhid said:","“Both Hands of al-Raḥmān are right.”"]},"n357":{"a":["قال الله تعالى:","﴿يَدُ اللهِ فَوْقَ أَيْدِيهِمْ﴾","[الفتح: ١٠]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আল্লাহর হাত তাদের হাতের ওপর।”","[সূরা আল-ফাতহ ৪৮:১০]"],"e":["Allah Most High said:","“The Hand of Allah is above their hands.”","[Sūrat al-Fatḥ 48:10]"]},"n359":{"a":["قال الله تعالى:","﴿وَتَقُولُ هَلْ مِنْ مَزِيدٍ﴾","[ق: ٣٠]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আর তা বলবে, ‘আরও আছে কি?’”","[সূরা কাফ ৫০:৩০]"],"e":["Allah Most High said:","“And it will say, ‘Is there any more?’”","[Sūrat Qāf 50:30]"]},"n365":{"a":["قال الله تعالى:","﴿يَوْمَ يُكْشَفُ عَنْ سَاقٍ وَيُدْعَوْنَ إِلَى السُّجُودِ فَلَا يَسْتَطِيعُونَ ۝ خَاشِعَةً أَبْصَارُهُمْ تَرْهَقُهُمْ ذِلَّةٌ وَقَدْ كَانُوا يُدْعَوْنَ إِلَى السُّجُودِ وَهُمْ سَالِمُونَ﴾","[القلم: ٤٢–٤٣]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“যেদিন পিণ্ডলি উন্মোচিত হবে এবং তাদের সিজদা করতে ডাকা হবে, কিন্তু তারা সক্ষম হবে না। তাদের দৃষ্টি অবনত থাকবে, লাঞ্ছনা তাদের আচ্ছন্ন করবে; অথচ যখন তারা সুস্থ ছিল তখনই তাদের সিজদা করতে ডাকা হতো।”","[সূরা আল-কলম ৬৮:৪২–৪৩]"],"e":["Allah Most High said:","“On the Day when the Shin will be uncovered and they will be called to prostrate, but they will not be able. Their eyes humbled, humiliation will overwhelm them, for they had been called to prostrate while they were sound.”","[Sūrat al-Qalam 68:42–43]"]},"n390":{"a":["قال الله تعالى:","﴿إِنَّ اللهَ لَا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلًا مَا بَعُوضَةً فَمَا فَوْقَهَا﴾","[البقرة: ٢٦]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“নিশ্চয়ই আল্লাহ কোনো দৃষ্টান্ত পেশ করতে লজ্জাবোধ করেন না—মশা হোক বা তার চেয়েও ক্ষুদ্র কিংবা বৃহৎ কিছু।”","[সূরা আল-বাকারা ২:২৬]"],"e":["Allah Most High said:","“Indeed, Allah is not ashamed to present an example — that of a mosquito or what is above it.”","[Sūrat al-Baqarah 2:26]"]},"n400":{"a":["قال الله تعالى:","﴿وَإِنْ أَحَدٌ مِنَ الْمُشْرِكِينَ اسْتَجَارَكَ فَأَجِرْهُ حَتَّى يَسْمَعَ كَلَامَ اللهِ﴾","[التوبة: ٦]","وقال تعالى:","﴿وَكَلَّمَ اللهُ مُوسَى تَكْلِيمًا﴾","[النساء: ١٦٤]","وقال تعالى:","﴿فَلَمَّا أَتَاهَا نُودِيَ مِنْ شَاطِئِ الْوَادِ الْأَيْمَنِ فِي الْبُقْعَةِ الْمُبَارَكَةِ مِنَ الشَّجَرَةِ أَنْ يَا مُوسَى إِنِّي أَنَا اللهُ رَبُّ الْعَالَمِينَ﴾","[القصص: ٣٠]","ففي هذه الآيات خاطب الله موسى عليه السلام، وكلمه بصوت مسموع وحروف سمعت، ولا يجوز أن يخاطبه ملك مقرب أو غير مقرب أو مخلوق آخر بقوله: «إني أنا الله رب العالمين»."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আর মুশরিকদের কেউ যদি আপনার কাছে আশ্রয় চায়, তবে তাকে আশ্রয় দিন, যাতে সে আল্লাহর কালাম শুনতে পারে।”","[সূরা আত-তাওবাহ ৯:৬]","আর তিনি সর্বোচ্চ বলেছেন:","“আর আল্লাহ মূসার সঙ্গে সরাসরি কথা বলেছেন।”","[সূরা আন-নিসা ৪:১৬৪]","আর তিনি সর্বোচ্চ বলেছেন:","“কিন্তু যখন তিনি সেখানে পৌঁছালেন, তখন উপত্যকার ডান পাশ থেকে, বরকতময় স্থানে, গাছের দিক থেকে তাঁকে ডাকা হলো: ‘হে মূসা, নিশ্চয়ই আমিই আল্লাহ, সকল জগতের রব।’”","[সূরা আল-কাসাস ২৮:৩০]","এই আয়াতসমূহে আল্লাহ মূসা (আলাইহিস সালাম)-কে সম্বোধন করেছেন এবং তাঁর সঙ্গে শ্রুত কণ্ঠ ও শোনা যায় এমন শব্দে কথা বলেছেন। কোনো নিকটবর্তী ফেরেশতা, অন্য কোনো ফেরেশতা অথবা অন্য কোনো সৃষ্টি তাঁকে এই কথা দিয়ে সম্বোধন করবে—এটি সম্ভব নয়:","“নিশ্চয়ই আমিই আল্লাহ, সকল জগতের রব।”"],"e":["Allah Most High said:","“And if any one of the polytheists seeks your protection, then grant him protection so that he may hear the Speech of Allah.”","[Sūrat al-Tawbah 9:6]","And He Most High said:","“And Allah spoke to Moses directly.”","[Sūrat al-Nisāʾ 4:164]","And He Most High said:","“But when he came to it, he was called from the right side of the valley, in the blessed spot, from the tree: ‘O Moses, indeed I am Allah, Lord of the worlds.’”","[Sūrat al-Qaṣaṣ 28:30]","In these verses, Allah addressed Moses, peace be upon him, and spoke to him with an audible voice and words that were heard. It is not possible that a near angel, any other angel, or another created being would address him with the words:","“Indeed, I am Allah, Lord of the worlds.”"]},"n413":{"a":["قال الله تعالى:","﴿وَمَا كَانَ لِبَشَرٍ أَنْ يُكَلِّمَهُ اللهُ إِلَّا وَحْيًا أَوْ مِنْ وَرَاءِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِيَ بِإِذْنِهِ مَا يَشَاءُ﴾","[الشورى: ٥١]","وقوله:","﴿إِلَّا وَحْيًا﴾","وهو شامل للوحي الذي يلقيه الله عز وجل على قلوب الأنبياء والرسل في حال اليقظة، ويشمل أيضاً الوحي الذي يريهم الله في المنام، كما قالت عائشة رضي الله عنها:","أول ما بُدئ به رسول الله ﷺ الرؤيا الصادقة في النوم.","وقوله تعالى:","﴿أَوْ مِنْ وَرَاءِ حِجَابٍ﴾","هو كما كلم الله موسى عليه السلام من وراء حجاب.","والحجاب المذكور في هذا الموضع وغيره يرجع إلى الخلق دون الخالق."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“কোনো মানুষের জন্য এমন নয় যে আল্লাহ তার সঙ্গে কথা বলবেন, তবে ওহীর মাধ্যমে, অথবা পর্দার আড়াল থেকে, অথবা একজন রাসূল প্রেরণ করে—তখন তিনি তাঁর অনুমতিতে যা চান তা ওহী করেন।”","[সূরা আশ-শূরা ৪২:৫১]","তাঁর বাণী:","“তবে ওহীর মাধ্যমে”","এর অন্তর্ভুক্ত হলো সেই ওহী যা আল্লাহ মহাপরাক্রমশালী ও মহিমান্বিত নবী ও রাসূলদের জাগ্রত অবস্থায় তাদের অন্তরে নিক্ষেপ করেন। এর অন্তর্ভুক্ত সেই ওহীও যা আল্লাহ তাদের স্বপ্নে দেখান; যেমন আয়িশাহ (রাদিয়াল্লাহু আনহা) বলেছেন:","“রাসূলুল্লাহ ﷺ-এর কাছে ওহীর সূচনা হয়েছিল ঘুমের মধ্যে সত্য স্বপ্নের মাধ্যমে।”","তাঁর বাণী:","“অথবা পর্দার আড়াল থেকে”","যেমন আল্লাহ মূসা (আলাইহিস সালাম)-এর সঙ্গে পর্দার আড়াল থেকে কথা বলেছেন।","এখানে এবং অন্যত্র যে পর্দার উল্লেখ এসেছে, তা সৃষ্ট বান্দার সঙ্গে সম্পর্কিত, স্রষ্টার সঙ্গে নয়।"],"e":["Allah Most High said:","“It is not for any human being that Allah should speak to him except by revelation, or from behind a veil, or by sending a messenger to reveal by His permission whatever He wills.”","[Sūrat al-Shūrā 42:51]","His statement:","“Except by revelation”","includes revelation which Allah, Mighty and Majestic, casts into the hearts of prophets and messengers while they are awake. It also includes revelation which Allah shows them in dreams, as ʿĀʾishah may Allah be pleased with her said:","“The first thing with which revelation began for the Messenger of Allah ﷺ was truthful dreams during sleep.”","His statement:","“Or from behind a veil”","is like Allah’s speaking to Moses, peace be upon him, from behind a veil.","The veil mentioned in this passage and elsewhere pertains to the created servant, not to the Creator."]},"n414":{"a":["القرآن كلام الله، وكلام الله صفة من صفات ذاته، وليس شيء من صفات ذاته مخلوقاً، ولا محدثاً، ولا حادثاً.","والأدلة على ذلك من كلام الله:","﴿إِنَّمَا قَوْلُنَا لِشَيْءٍ إِذَا أَرَدْنَاهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ﴾","[النحل: ٤٠]","فلو كان القرآن مخلوقاً لكان مخلوقاً بـ«كن»، ويستحيل أن يكون قول الله لشيء بقول؛ لأنه يوجب قولاً ثانياً وثالثاً يتسلسل، وهو فاسد.","وقال تعالى:","﴿الرَّحْمَنُ ۝ عَلَّمَ الْقُرْآنَ ۝ خَلَقَ الْإِنْسَانَ﴾","[الرحمن: ١–٣]","فخص القرآن بالتعليم؛ لأنه كلامه وصفته، وخص الإنسان بالتخليق؛ لأنه خلقه ومصنوعه، ولولا ذلك لقال: خلق القرآن والإنسان.","وقال تعالى:","﴿وَكَلَّمَ اللهُ مُوسَى تَكْلِيمًا﴾","[النساء: ١٦٤]","ولا يجوز أن يكون كلام المتكلم قائماً بغيره.","وقد أنكر الله تعالى قول المشركين:","﴿إِنْ هَذَا إِلَّا قَوْلُ الْبَشَرِ﴾","[المدثر: ٢٥]","فمن زعم أن القرآن مخلوق فقد جعله قولاً للبشر."],"b":["কুরআন আল্লাহর কালাম। আল্লাহর কালাম তাঁর সত্তাগত গুণাবলির একটি, আর তাঁর সত্তাগত কোনো গুণই সৃষ্ট বা নবসৃষ্ট নয়।","আল্লাহর কালাম থেকেই এর প্রমাণসমূহের একটি হলো:","“আমি যখন কোনো কিছুর ইচ্ছা করি, তখন তার প্রতি আমার কথা কেবল এই যে আমি বলি, ‘হও’, আর তা হয়ে যায়।”","[সূরা আন-নাহল ১৬:৪০]","কুরআন যদি সৃষ্ট হতো, তবে সেটিও “হও” আদেশের মাধ্যমে সৃষ্ট হতো। কিন্তু আল্লাহর “হও” বলার জন্য আবার আরেকটি সৃষ্ট বক্তব্য প্রয়োজন হবে—এটি অসম্ভব; কারণ তাহলে তার আগেও আরেকটি বক্তব্য, তারপর আরেকটি বক্তব্য প্রয়োজন হতো এবং এভাবে অন্তহীনভাবে চলতে থাকত, যা বাতিল।","আল্লাহ সর্বোচ্চ বলেছেন:","“আর-রহমান। তিনি কুরআন শিক্ষা দিয়েছেন। তিনি মানুষ সৃষ্টি করেছেন।”","[সূরা আর-রহমান ৫৫:১–৩]","কুরআনকে বিশেষভাবে শিক্ষা দেওয়া হয়েছে বলে বর্ণনা করা হয়েছে, কারণ এটি তাঁর কালাম ও গুণ; আর মানুষকে বিশেষভাবে সৃষ্টি করা হয়েছে বলে বর্ণনা করা হয়েছে, কারণ মানুষ তাঁর সৃষ্টি ও নির্মাণ। অন্যথায় বলা হতো যে তিনি কুরআন ও মানুষ উভয়কেই সৃষ্টি করেছেন।","আল্লাহ সর্বোচ্চ বলেছেন:","“আর আল্লাহ মূসার সঙ্গে সরাসরি কথা বলেছেন।”","[সূরা আন-নিসা ৪:১৬৪]","কোনো বক্তার কথা বক্তা ছাড়া অন্য কারও মধ্যে বিদ্যমান বলা যায় না।","আল্লাহ সর্বোচ্চ মুশরিকদের এই বক্তব্যের নিন্দা করেছেন:","“এ তো কেবল একজন মানুষের কথা।”","[সূরা আল-মুদ্দাসসির ৭৪:২৫]","অতএব পাণ্ডুলিপিতে বলা হয়েছে, যে ব্যক্তি কুরআনকে সৃষ্ট বলে দাবি করে, সে এর মাধ্যমে কুরআনকে সৃষ্ট কথার পর্যায়ে নামিয়ে আনে।"],"e":["The Qurʾān is the Speech of Allah. The Speech of Allah is one of the Attributes of His Essence, and none of the Attributes of His Essence is created or originated.","Among the evidences for this from the Speech of Allah is:","“Our word to a thing, when We intend it, is only that We say to it, ‘Be,’ and it is.”","[Sūrat al-Naḥl 16:40]","If the Qurʾān were created, it would itself have been created by the command “Be.” It is impossible that Allah’s act of saying “Be” should itself require another created statement, for that would require another statement before it, then another, continuing without end, which is invalid.","Allah Most High said:","“The Most Merciful. He taught the Qurʾān. He created mankind.”","[Sūrat al-Raḥmān 55:1–3]","The Qurʾān was specifically described as being taught because it is His Speech and Attribute, whereas mankind was specifically described as being created because mankind is His creation and handiwork. Otherwise, it would have said that He created both the Qurʾān and mankind.","Allah Most High said:","“And Allah spoke to Moses directly.”","[Sūrat al-Nisāʾ 4:164]","The speech of a speaker cannot be said to subsist in someone other than the speaker himself.","Allah Most High condemned the statement of the polytheists:","“This is nothing but the speech of a human being.”","[Sūrat al-Muddaththir 74:25]","Thus, the manuscript states that whoever claims the Qurʾān to be created has thereby reduced it to created speech."]},"n416":{"a":["قال الله تعالى:","﴿عَالِمُ الْغَيْبِ فَلَا يُظْهِرُ عَلَى غَيْبِهِ أَحَدًا﴾","[الجن: ٢٦]","وقال تعالى:","﴿إِنَّ اللهَ عِنْدَهُ عِلْمُ السَّاعَةِ﴾","[لقمان: ٣٤]","وقال تعالى:","﴿أَنْزَلَهُ بِعِلْمِهِ﴾","[النساء: ١٦٦]","وقال تعالى:","﴿وَمَا تَحْمِلُ مِنْ أُنْثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ﴾","[فاطر: ١١؛ فصلت: ٤٧]","وقال تعالى:","﴿إِلَيْهِ يُرَدُّ عِلْمُ السَّاعَةِ﴾","[فصلت: ٤٧]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“তিনি অদৃশ্যের জ্ঞানী, এবং তিনি তাঁর অদৃশ্য কাউকে প্রকাশ করেন না।”","[সূরা আল-জিন্ন ৭২:২৬]","আর তিনি বলেছেন:","“নিশ্চয়ই কিয়ামতের জ্ঞান একমাত্র আল্লাহর কাছেই রয়েছে।”","[সূরা লুকমান ৩১:৩৪]","আর তিনি বলেছেন:","“তিনি তা তাঁর জ্ঞানসহ নাযিল করেছেন।”","[সূরা আন-নিসা ৪:১৬৬]","আর তিনি বলেছেন:","“কোনো নারী তাঁর জ্ঞান ছাড়া গর্ভধারণ করে না এবং সন্তান প্রসবও করে না।”","[সূরা ফাতির ৩৫:১১; সূরা ফুসসিলাত ৪১:৪৭]","আর তিনি বলেছেন:","“কিয়ামতের জ্ঞান কেবল তাঁরই দিকে প্রত্যাবর্তিত হয়।”","[সূরা ফুসসিলাত ৪১:৪৭]"],"e":["Allah Most High said:","“Knower of the unseen, and He does not disclose His unseen to anyone.”","[Sūrat al-Jinn 72:26]","And He said:","“Indeed, Allah alone has knowledge of the Hour.”","[Sūrat Luqmān 31:34]","And He said:","“He sent it down with His knowledge.”","[Sūrat al-Nisāʾ 4:166]","And He said:","“No female conceives or gives birth except with His knowledge.”","[Sūrat Fāṭir 35:11; Sūrat Fuṣṣilat 41:47]","And He said:","“To Him alone is referred the knowledge of the Hour.”","[Sūrat Fuṣṣilat 41:47]"]},"n418":{"a":["قال الله تعالى:","﴿وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ﴾","[الحديد: ٤]","وقال تعالى:","﴿مَا يَكُونُ مِنْ نَجْوَى ثَلَاثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَا أَدْنَى مِنْ ذَلِكَ وَلَا أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا﴾","[المجادلة: ٧]","وقال لموسى وهارون حين أرسلهما إلى فرعون:","﴿لَا تَخَافَا إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَى﴾","[طه: ٤٦]","وحكى الله قول رسوله محمد ﷺ حين قال لصاحبه أبي بكر رضي الله عنه:","﴿إِذْ هُمَا فِي الْغَارِ إِذْ يَقُولُ لِصَاحِبِهِ لَا تَحْزَنْ إِنَّ اللهَ مَعَنَا﴾","[التوبة: ٤٠]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“তোমরা যেখানেই থাকো, তিনি তোমাদের সঙ্গে আছেন।”","[সূরা আল-হাদীদ ৫৭:৪]","আর তিনি বলেছেন:","“তিনজনের কোনো গোপন কথোপকথন হয় না যেখানে তিনি তাদের চতুর্থ নন; পাঁচজনেরও নয় যেখানে তিনি তাদের ষষ্ঠ নন; এর চেয়ে কম বা বেশি হলেও তারা যেখানেই থাকুক না কেন তিনি তাদের সঙ্গে আছেন।”","[সূরা আল-মুজাদিলাহ ৫৮:৭]","আর তিনি মূসা ও হারূনকে ফিরআউনের কাছে পাঠানোর সময় বলেছেন:","“ভয় করো না। নিশ্চয়ই আমি তোমাদের উভয়ের সঙ্গে আছি; আমি শুনি এবং দেখি।”","[সূরা ত্ব-হা ২০:৪৬]","আল্লাহ তাঁর রাসূল মুহাম্মাদ ﷺ-এর কথাও বর্ণনা করেছেন, যখন তিনি তাঁর সঙ্গী আবূ বকর (রাদিয়াল্লাহু আনহু)-কে বলেছিলেন:","“যখন তারা দুজন গুহায় ছিল এবং তিনি তাঁর সঙ্গীকে বলেছিলেন: ‘দুঃখ করো না; নিশ্চয়ই আল্লাহ আমাদের সঙ্গে আছেন।’”","[সূরা আত-তাওবাহ ৯:৪০]"],"e":["Allah Most High said:","“He is with you wherever you may be.”","[Sūrat al-Ḥadīd 57:4]","And He said:","“There is no private conversation among three except that He is their fourth, nor among five except that He is their sixth, nor fewer than that nor more except that He is with them wherever they may be.”","[Sūrat al-Mujādilah 58:7]","And He said to Moses and Aaron when He sent them to Pharaoh:","“Do not fear. Indeed, I am with you both; I hear and I see.”","[Sūrat Ṭā Hā 20:46]","Allah also related the words of His Messenger Muḥammad ﷺ when he said to his companion Abū Bakr may Allah be pleased with him:","“When the two of them were in the cave and he said to his companion: ‘Do not grieve; indeed, Allah is with us.’”","[Sūrat al-Tawbah 9:40]"]},"n420":{"a":["قال الله تعالى:","﴿لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ﴾","[الشورى: ١١]","وقال تعالى:","﴿هَلْ تَعْلَمُ لَهُ سَمِيًّا﴾","[مريم: ٦٥]","وقال تعالى:","﴿فَلَا تَضْرِبُوا لِلَّهِ الْأَمْثَالَ﴾","[النحل: ٧٤]","ضلَّت طائفتان في أسماء الله تعالى وصفاته:","إحداهما: المشبهة، وهم الذين شبهوا الله بخلقه، وجعلوا صفاته من جنس صفات المخلوقين.","وأول من أظهر هذه المقالة هشام بن الحكم الرافضي، مات بعد نكبة البرامكة بمدة مستتراً، ويقال: عاش إلى خلافة المأمون.","وبيان بن سمعان التميمي، وهو أيضاً من غلاة الشيعة، كان يقول بألوهية علي رضي الله عنه، ومن بعده من أولاده، وكان يقول: إن معبوده نور، وصورته صورة إنسان، وله أعضاء كأعضاء الإنسان، وأن جميع أعضائه تفنى إلا الوجه.","وهذان أخذا هذه المقالة من النصارى والهندوس الذين شبهوا الله تعالى بالمخلوقين.","والثانية: المعطلة، الذين نفوا عن الله جميع صفاته التي وصف بها نفسه، ووصفه بها رسوله ﷺ، زاعمين أن إثباتها يؤدي إلى التشبيه والتجسيم.","وأول من دعا إلى هذه المقالة الجعد بن درهم، فأنكر تكليم الله موسى بكلام مسموع، فرُفع أمره إلى خالد بن عبد الله القسري، وكان أميراً على العراق من قبل هشام بن عبد الملك بن مروان.","ففي يوم عيد الأضحى صعد المنبر، فخطب خطبة بليغة، ثم قال:","ارجعوا فضحوا، تقبل الله منكم، فإني مضحٍّ بالجعد بن درهم؛ إنه زعم أن الله لم يكلم موسى تكليماً، ولم يتخذ إبراهيم خليلاً.","ثم نزل وذكاه تحت المنبر بمحضر من الخاصة والعامة، فاستحسن الكل فعله، وذلك في سنة ١٢٤هـ.","وأخذ عنه هذا المذهب الجهم بن صفوان (١٢٨هـ)، ونسب إليه هذا المذهب، وتأثر بهذه المقالة كل من المعتزلة والأشاعرة.","هذه القصة ذكرها البخاري في خلق أفعال العباد (رقم ٣)، واللالكائي في اعتقاد أهل السنة (٢/٣١٩)، والدارمي في الرد على الجهمية (ص ٢١)، والبيهقي في السنن الكبرى (١٠/٢٠٥)، من طرق عن عبد الرحمن بن محمد بن حبيب بن أبي حبيب، عن أبيه، عن جده حبيب بن أبي حبيب قال:","خطبنا خالد بن عبد الله القسري بواسط يوم الأضحى…","فذكره.","وعبد الرحمن وأبوه مجهولان، إلا أن هذه القصة اشتهرت بين الناس، فاستغنت عن ذكر الإسناد.","ذكره أيضاً الذهبي في سير أعلام النبلاء (٥/٤٣٢) في ترجمة خالد بن عبد الله بن يزيد القسري الدمشقي، أمير العراق لهشام، وقال:","«هذه من حسناته».","فالمعطلة ينفون عن الله جميع الأسماء والصفات.","والمعتزلة يثبتون الأسماء المجردة عن معانيها، وينفون عنه الصفات.","والأشاعرة يثبتون الأسماء وسبع صفات فقط، وهي: العلم، والحياة، والقدرة، والإرادة، والسمع، والبصر، والكلام، وينفون عنه بقية الصفات.","وشبهة هؤلاء فيما نفوه من الصفات أن إثباتها يقتضي التشبيه والتجسيم حسب زعمهم، ويسمون من أثبتها مشبهة ومجسمة.","وهدى الله أهل السنة والجماعة، فإنهم يثبتون من الأسماء والصفات ما أثبته الله لنفسه، أو أثبته له رسوله ﷺ، من غير تحريف ولا تأويل ولا تشبيه."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“তাঁর সদৃশ কোনো কিছুই নেই, আর তিনি সর্বশ্রোতা, সর্বদ্রষ্টা।”","[সূরা আশ-শূরা ৪২:১১]","আর তিনি বলেছেন:","“তুমি কি তাঁর কোনো সমনাম বা সমতুল্য কাউকে জানো?”","[সূরা মারইয়াম ১৯:৬৫]","আর তিনি বলেছেন:","“অতএব আল্লাহর জন্য উপমা স্থির করো না।”","[সূরা আন-নাহল ১৬:৭৪]","পাণ্ডুলিপিতে বলা হয়েছে, আল্লাহ সর্বোচ্চের নাম ও গুণাবলি সম্পর্কে দুই দল পথভ্রষ্ট হয়েছে।","প্রথম দল হলো মুশাব্বিহাহ: যারা আল্লাহকে তাঁর সৃষ্টির সঙ্গে সাদৃশ্যপূর্ণ করেছে এবং তাঁর গুণাবলিকে সৃষ্টির গুণাবলির একই প্রকৃতির বলে গণ্য করেছে।","পাণ্ডুলিপিতে এই মতবাদের প্রাথমিক প্রকাশ্য প্রবক্তাদের মধ্যে হিশাম ইবনুল হাকাম আর-রাফিদীর নাম উল্লেখ করা হয়েছে। এতে বলা হয়েছে যে বারামিকাদের পতনের কিছু সময় পর তিনি আত্মগোপন অবস্থায় মৃত্যুবরণ করেন; অন্য একটি বর্ণনা অনুযায়ী তিনি আল-মামূনের খেলাফত পর্যন্ত জীবিত ছিলেন।","এতে বায়ান ইবন সাম‘আন আত-তামীমীর কথাও উল্লেখ করা হয়েছে; তাকে চরমপন্থী শী‘আদের একজন হিসেবে বর্ণনা করা হয়েছে, যে আলী এবং পরে তাঁর কিছু বংশধরের জন্য উলূহিয়্যাতের দাবি করেছিল। তার প্রতি এই দাবিও আরোপ করা হয়েছে যে তার উপাস্য ছিল আলো, মানুষের আকৃতিতে, মানুষের অঙ্গের মতো অঙ্গবিশিষ্ট, এবং মুখমণ্ডল ছাড়া তার সব অঙ্গ ধ্বংস হয়ে যাবে।","পাণ্ডুলিপিতে বলা হয়েছে, এই মতবাদগুলো খ্রিস্টান ও হিন্দুদের কাছ থেকে নেওয়া হয়েছিল, যারা আল্লাহ সর্বোচ্চকে সৃষ্টির সঙ্গে সাদৃশ্যপূর্ণ করেছিল।","উল্লেখিত দ্বিতীয় দল হলো মু‘আত্তিলাহ: যারা আল্লাহ নিজেকে যেসব গুণে বর্ণনা করেছেন এবং তাঁর রাসূল ﷺ যেসব গুণে তাঁকে বর্ণনা করেছেন সেগুলো অস্বীকার করে; তাদের দাবি হলো, এসব গুণ সাব্যস্ত করলে তা মানবসদৃশকরণ ও দেহবাদে নিয়ে যায়।","পাণ্ডুলিপিতে আল-জা‘দ ইবন দিরহামকে এই অবস্থানের একজন প্রাথমিক প্রবক্তা হিসেবে চিহ্নিত করা হয়েছে এবং বলা হয়েছে যে সে অস্বীকার করত—আল্লাহ মূসার সঙ্গে শ্রুত কালামের মাধ্যমে কথা বলেছেন। তার বিষয়টি খালিদ ইবন আবদিল্লাহ আল-কাসরীর কাছে উপস্থাপিত হয়, যিনি হিশাম ইবন আবদুল মালিক ইবন মারওয়ানের শাসনামলে ইরাকের গভর্নর ছিলেন।","এরপর পাণ্ডুলিপিতে বর্ণনা করা হয়েছে যে ঈদুল আযহার দিন খালিদ মিম্বরে উঠে একটি বাগ্মীতাপূর্ণ খুতবা দেন, তারপর বলেন:","“তোমরা ফিরে যাও এবং তোমাদের কুরবানী করো—আল্লাহ তা তোমাদের কাছ থেকে কবুল করুন—আর আমি আল-জা‘দ ইবন দিরহামকে কুরবানী করতে যাচ্ছি। সে দাবি করেছে যে আল্লাহ মূসার সঙ্গে সরাসরি কথা বলেননি এবং ইবরাহীমকে অন্তরঙ্গ বন্ধু হিসেবে গ্রহণ করেননি।”","এতে বলা হয়েছে, এরপর তিনি মিম্বর থেকে নেমে বিশিষ্ট ব্যক্তি ও সাধারণ মানুষের উপস্থিতিতে তাকে হত্যা করেন এবং ঘটনাটির সাল ১২৪ হিজরি হিসেবে উল্লেখ করা হয়েছে।","পাণ্ডুলিপিতে আরও বলা হয়েছে, ১২৮ হিজরিতে মৃত্যুবরণকারী জাহম ইবন সফওয়ান আল-জা‘দের কাছ থেকে এই মতবাদ গ্রহণ করে; পরবর্তীতে মতবাদটি তার নামের সঙ্গে সম্পর্কিত হয়ে যায়; এবং মু‘তাযিলা ও আশ‘আরীগণও এসব ধারণার দ্বারা প্রভাবিত হয়েছিল।","এই বিবরণ আল-বুখারী ‘খালক আফ‘আল আল-‘ইবাদ’ (নং ৩), আল-লালাকাঈ ‘ই‘তিকাদ আহলিস সুন্নাহ’ (২/৩১৯), আদ-দারিমী ‘আর-রাদ্দ ‘আলাল জাহমিয়্যাহ’ (পৃ. ২১) এবং আল-বায়হাকী ‘আস-সুনান আল-কুবরা’ (১০/২০৫)-এ আবদুর রহমান ইবন মুহাম্মাদ ইবন হাবীব ইবন আবী হাবীবের সূত্রে, তার পিতা থেকে, তার দাদা হাবীব ইবন আবী হাবীব থেকে বর্ণনা করেছেন। তিনি বলেছেন:","“খালিদ ইবন আবদিল্লাহ আল-কাসরী ওয়াসিতে আমাদের উদ্দেশে ঈদুল আযহার খুতবা দিয়েছিলেন…”","এরপর তিনি ঘটনাটি উল্লেখ করেন।","পাণ্ডুলিপিতে উল্লেখ করা হয়েছে যে আবদুর রহমান ও তার পিতা অজ্ঞাতপরিচয় বর্ণনাকারী; তবে এতে বলা হয়েছে যে ঘটনাটি মানুষের মধ্যে ব্যাপকভাবে পরিচিত হয়ে গিয়েছিল।","আয-যাহাবীও ‘সিয়ার আ‘লাম আন-নুবালা’ (৫/৪৩২)-এ খালিদ ইবন আবদিল্লাহ ইবন ইয়াযীদ আল-কাসরী আদ-দিমাশকীর জীবনীতে, যিনি হিশামের অধীনে ইরাকের গভর্নর ছিলেন, ঘটনাটি উল্লেখ করেছেন এবং বলেছেন:","“এটি ছিল তার সৎকর্মসমূহের একটি।”","পাণ্ডুলিপিতে মতগুলো এভাবে ব্যাখ্যা করা হয়েছে:","মু‘আত্তিলাহ আল্লাহর নাম ও গুণাবলি অস্বীকার করে।","মু‘তাযিলা নামসমূহ সাব্যস্ত করে, কিন্তু পাণ্ডুলিপির ভাষ্য অনুযায়ী সেগুলোকে তাদের অর্থ থেকে শূন্য করে এবং গুণাবলি অস্বীকার করে।","আশ‘আরীগণ নামসমূহ এবং সাতটি গুণ—জ্ঞান, জীবন, ক্ষমতা, ইচ্ছা, শ্রবণ, দর্শন ও কালাম—সাব্যস্ত করে; তবে পাণ্ডুলিপিতে বলা হয়েছে, তারা অবশিষ্ট গুণাবলি একই পদ্ধতিতে সাব্যস্ত করে না।","পাণ্ডুলিপি তাদের যেসব গুণ তারা সাব্যস্ত করে না সে সম্পর্কে তাদের যুক্তি এভাবে ব্যাখ্যা করেছে: তাদের মতে এসব গুণ সাব্যস্ত করা অবশ্যম্ভাবীভাবে মানবসদৃশকরণ বা দেহবাদকে আবশ্যক করে; তাই তারা এসব গুণ সাব্যস্তকারীদের মুশাব্বিহাহ বা মুজাসসিমাহ বলে আখ্যায়িত করে।","পাণ্ডুলিপি এ আলোচনা শেষ করেছে এই বলে যে আহলুস সুন্নাহ ওয়াল জামা‘আহ আল্লাহর নাম ও গুণাবলি সম্পর্কে সেই সবকিছুই সাব্যস্ত করে যা আল্লাহ নিজের জন্য সাব্যস্ত করেছেন অথবা তাঁর রাসূল ﷺ তাঁর জন্য সাব্যস্ত করেছেন—কোনো বিকৃতি, রূপক পুনর্ব্যাখ্যা বা আল্লাহকে তাঁর সৃষ্টির সঙ্গে সাদৃশ্য প্রদান ছাড়াই।"],"e":["Allah Most High said:","“There is nothing whatsoever like Him, and He is the All-Hearing, the All-Seeing.”","[Sūrat al-Shūrā 42:11]","And He said:","“Do you know of any namesake or equal to Him?”","[Sūrat Maryam 19:65]","And He said:","“So do not set forth comparisons for Allah.”","[Sūrat al-Naḥl 16:74]","The manuscript states that two groups went astray concerning the Names and Attributes of Allah Most High.","The first are the Mushabbihah: those who likened Allah to His creation and regarded His Attributes as being of the same kind as the attributes of created beings.","The manuscript identifies among the earliest public proponents of this doctrine Hishām ibn al-Ḥakam al-Rāfiḍī. It states that he died sometime after the downfall of the Barmakids while living in concealment, while another report holds that he survived until the caliphate of al-Maʾmūn.","It also mentions Bayān ibn Samʿān al-Tamīmī, describing him as one of the extremist Shīʿah who claimed divinity for ʿAlī and afterward for some of his descendants. It attributes to him the claim that the object of his worship was light, in human form, possessing limbs like human limbs, and that all its limbs would perish except the face.","The manuscript states that these doctrines were taken from Christians and Hindus who likened Allah Most High to created beings.","The second group mentioned is the Muʿaṭṭilah: those who negate the Attributes by which Allah described Himself and by which His Messenger ﷺ described Him, claiming that affirming them leads to anthropomorphic resemblance and corporealism.","The manuscript identifies al-Jaʿd ibn Dirham as an early advocate of this position and states that he denied that Allah spoke to Moses with audible speech. His case was brought before Khālid ibn ʿAbdillāh al-Qasrī, who was governor of Iraq under Hishām ibn ʿAbd al-Malik ibn Marwān.","The manuscript then relates that on the Day of ʿĪd al-Aḍḥā, Khālid ascended the pulpit and delivered an eloquent sermon, then said:","“Return and offer your sacrifices — may Allah accept them from you — for I am going to sacrifice al-Jaʿd ibn Dirham. He claimed that Allah did not speak directly to Moses and did not take Abraham as a close friend.”","It states that he then descended and killed him beneath the pulpit in the presence of both prominent people and the general public, and dates this event to 124 AH.","It further states that Jahm ibn Ṣafwān, who died in 128 AH, took this doctrine from al-Jaʿd, that the doctrine subsequently became associated with his name, and that the Muʿtazilah and Ashʿarīs were influenced by these ideas.","This account was mentioned by al-Bukhārī in Khalq Afʿāl al-ʿIbād (no. 3), al-Lālakāʾī in Iʿtiqād Ahl al-Sunnah (2/319), al-Dārimī in al-Radd ʿalā al-Jahmiyyah (p. 21), and al-Bayhaqī in al-Sunan al-Kubrā (10/205), through chains from ʿAbd al-Raḥmān ibn Muḥammad ibn Ḥabīb ibn Abī Ḥabīb, from his father, from his grandfather Ḥabīb ibn Abī Ḥabīb, who said:","“Khālid ibn ʿAbdillāh al-Qasrī delivered the ʿĪd al-Aḍḥā sermon to us at Wāsiṭ…”","and then mentioned the account.","The manuscript notes that ʿAbd al-Raḥmān and his father are unknown narrators, but states that the account became widely known among the people.","It was also mentioned by al-Dhahabī in Siyar Aʿlām al-Nubalāʾ (5/432), in his biography of Khālid ibn ʿAbdillāh ibn Yazīd al-Qasrī al-Dimashqī, governor of Iraq for Hishām, where he said:","“This was among his good deeds.”","The manuscript describes the positions as follows:","The Muʿaṭṭilah negate Allah’s Names and Attributes.","The Muʿtazilah affirm the Names while, according to the manuscript, stripping them of their meanings, and they negate the Attributes.","The Ashʿarīs affirm the Names and seven Attributes — knowledge, life, power, will, hearing, sight, and speech — while the manuscript states that they do not affirm the remaining Attributes in the same manner.","The manuscript explains their argument concerning the Attributes they do not affirm as being that, in their view, affirming such Attributes necessarily entails anthropomorphic resemblance or corporealism; accordingly, they label those who affirm them as Mushabbihah or Mujassimah.","The manuscript concludes this discussion by stating that Ahl al-Sunnah wa al-Jamāʿah affirm concerning the Names and Attributes whatever Allah affirmed for Himself or His Messenger ﷺ affirmed for Him, without distortion, figurative reinterpretation, or likening Allah to His creation."]},"n448":{"a":["قال الله تعالى:","﴿وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ ۝ إِلَى رَبِّهَا نَاظِرَةٌ﴾","[القيامة: ٢٢–٢٣]","وقال تعالى عن الكفار:","﴿كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ ۝ ثُمَّ إِنَّهُمْ لَصَالُوا الْجَحِيمِ ۝ ثُمَّ يُقَالُ هَذَا الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ﴾","[المطففين: ١٥–١٧]","أي: الكفار.","قال الشافعي رحمه الله:","«هذه الآية دليل على أن المؤمنين يرونه عز وجل يومئذ».","قول الأئمة من أهل السنة في رؤية الله تبارك وتعالى يوم القيامة","قال مالك رحمه الله:","«الناس ينظرون إلى الله تعالى يوم القيامة بأعينهم».","الشريعة للآجري (٥٧٤).","وقال الإمام أحمد رحمه الله:","«من قال إن الله تعالى لا يُرى في الآخرة فقد كفر، وعليه لعنة الله وغضبه. أليس الله عز وجل يقول:","﴿وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ ۝ إِلَى رَبِّهَا نَاظِرَةٌ﴾","وقال تعالى:","﴿كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ﴾","هذا دليل على أن المؤمنين يرون الله تعالى».","الشريعة للآجري (٥٧٧).","وقال تعالى:","﴿لَا تُدْرِكُهُ الْأَبْصَارُ وَهُوَ يُدْرِكُ الْأَبْصَارَ وَهُوَ اللَّطِيفُ الْخَبِيرُ﴾","[الأنعام: ١٠٣]","ومعناه عند أهل العلم: أي لا تحيط به الأبصار ولا تحويه عز وجل، وهم يرونه من غير إدراك، ولا يشكون في رؤيته.","كما يقول الرجل:","رأيت السماء.","وهو صادق، ولم يحط بصره بكل السماء ولم يدركها.","وكما يقول الرجل:","رأيت البحر.","وهو صادق، ولم يدرك ببصره كل البحر، ولم يحط به ببصره.","ذكره الآجري في الشريعة (٢/١٠٤٨)."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“সেদিন কিছু মুখমণ্ডল হবে উজ্জ্বল, তারা তাদের রবের দিকে তাকিয়ে থাকবে।”","[সূরা আল-কিয়ামাহ ৭৫:২২–২৩]","আর কাফিরদের সম্পর্কে তিনি বলেছেন:","“কখনোই নয়! নিশ্চয়ই সেদিন তারা তাদের রব থেকে পর্দাবৃত থাকবে। তারপর অবশ্যই তারা জাহান্নামে প্রবেশ করবে। এরপর বলা হবে: ‘এটাই তো সেই বিষয় যা তোমরা অস্বীকার করতে।’”","[সূরা আল-মুতাফফিফীন ৮৩:১৫–১৭]","অর্থাৎ কাফিররা।","আশ-শাফিঈ (রহিমাহুল্লাহ) বলেছেন:","“এই আয়াত প্রমাণ করে যে সেদিন মুমিনরা তাঁকে, মহাপরাক্রমশালী ও মহিমান্বিতকে, দেখবে।”","কিয়ামতের দিন আল্লাহ বরকতময় ও সর্বোচ্চকে দেখা সম্পর্কে আহলুস সুন্নাহর ইমামদের বক্তব্য","মালিক (রহিমাহুল্লাহ) বলেছেন:","“কিয়ামতের দিন মানুষ তাদের চোখ দিয়ে আল্লাহ সর্বোচ্চের দিকে তাকাবে।”","আল-আজুররীর ‘আশ-শরী‘আহ’ (৫৭৪)।","ইমাম আহমাদ (রহিমাহুল্লাহ) বলেছেন:","“যে ব্যক্তি বলে যে আখিরাতে আল্লাহ সর্বোচ্চকে দেখা যাবে না, সে কুফর করেছে; তার ওপর আল্লাহর অভিশাপ ও ক্রোধ।","আল্লাহ মহাপরাক্রমশালী ও মহিমান্বিত কি বলেননি:","‘সেদিন কিছু মুখমণ্ডল হবে উজ্জ্বল, তারা তাদের রবের দিকে তাকিয়ে থাকবে’?","আর তিনি কি বলেননি:","‘কখনোই নয়! নিশ্চয়ই সেদিন তারা তাদের রব থেকে পর্দাবৃত থাকবে’?","এটি প্রমাণ করে যে মুমিনরা আল্লাহ সর্বোচ্চকে দেখবে।”","আল-আজুররীর ‘আশ-শরী‘আহ’ (৫৭৭)।","আল্লাহ সর্বোচ্চ বলেছেন:","“দৃষ্টিসমূহ তাঁকে পরিবেষ্টন করতে পারে না, অথচ তিনি সকল দৃষ্টিকে পরিবেষ্টন করেন; আর তিনি অতি সূক্ষ্মদর্শী, সর্বজ্ঞ।”","[সূরা আল-আন‘আম ৬:১০৩]","আলেমদের মতে এর অর্থ হলো—চোখের দৃষ্টি তাঁকে, মহাপরাক্রমশালী ও মহিমান্বিতকে, সম্পূর্ণভাবে পরিবেষ্টন বা আয়ত্ত করতে পারে না; যদিও মুমিনরা তাঁকে দেখবে, কিন্তু তাঁকে পরিবেষ্টন করতে পারবে না, এবং তাঁকে দেখা সম্পর্কে তাদের কোনো সন্দেহ থাকবে না।","এটি এমন, যেমন একজন ব্যক্তি বলে:","“আমি আকাশ দেখেছি।”","সে সত্য বলছে, যদিও তার দৃষ্টি সমগ্র আকাশকে পরিবেষ্টন করেনি।","অনুরূপভাবে একজন ব্যক্তি বলতে পারে:","“আমি সমুদ্র দেখেছি।”","সে সত্য বলছে, যদিও তার দৃষ্টি সমগ্র সমুদ্রকে পরিবেষ্টন করেনি।","আল-আজুররী ‘আশ-শরী‘আহ’ (২/১০৪৮)-এ এটি উল্লেখ করেছেন।"],"e":["Allah Most High said:","“Faces on that Day will be radiant, looking toward their Lord.”","[Sūrat al-Qiyāmah 75:22–23]","And He said concerning the disbelievers:","“No! Indeed, they will surely be veiled from their Lord on that Day. Then indeed they will enter the Hellfire. Then it will be said: ‘This is what you used to deny.’”","[Sūrat al-Muṭaffifīn 83:15–17]","That is, the disbelievers.","Al-Shāfiʿī, may Allah have mercy on him, said:","“This verse is evidence that the believers will see Him, Mighty and Majestic, on that Day.”","Statements of the Imams of Ahl al-Sunnah Concerning Seeing Allah, Blessed and Exalted, on the Day of Resurrection","“People will look at Allah Most High on the Day of Resurrection with their eyes.”","Al-Sharīʿah by al-Ājurrī (574).","Imām Aḥmad, may Allah have mercy on him, said:","“Whoever says that Allah Most High will not be seen in the Hereafter has disbelieved, and upon him is the curse and wrath of Allah.","Does Allah, Mighty and Majestic, not say:","‘Faces on that Day will be radiant, looking toward their Lord’?","And does He not say:","‘No! Indeed, they will surely be veiled from their Lord on that Day’?","This is evidence that the believers will see Allah Most High.”","Al-Sharīʿah by al-Ājurrī (577).","Allah Most High said:","“Vision does not encompass Him, while He encompasses all vision, and He is the Most Subtle, the All-Aware.”","[Sūrat al-Anʿām 6:103]","Its meaning according to the scholars is that eyesight does not completely encompass or contain Him, Mighty and Majestic, although the believers will see Him without encompassing Him, and they will have no doubt concerning their seeing Him.","This is like a man saying:","“I saw the sky.”","He speaks truthfully, although his sight did not encompass the entire sky.","Likewise, a man may say:","“I saw the sea.”","He speaks truthfully, although his sight did not encompass the entire sea.","Mentioned by al-Ājurrī in al-Sharīʿah (2/1048)."]},"n466":{"a":["قال الله تعالى:","﴿وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ﴾","[التوبة: ١٢٩]","وصف الله تعالى العرش بأنه مربوب، وكل مربوب مخلوق، فالعرش مخلوق.","وقال تعالى:","﴿وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ وَكَانَ عَرْشُهُ عَلَى الْمَاءِ﴾","[هود: ٧]","وليس المراد بالماء ماء البحر، بل هو ماء تحت العرش كما قال الله تعالى."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আর তিনিই মহান আরশের রব।”","[সূরা আত-তাওবাহ ৯:১২৯]","আল্লাহ সর্বোচ্চ আরশকে এমন এক বস্তু হিসেবে বর্ণনা করেছেন যার ওপর তিনি রবুবিয়্যাত করেন; আর তাঁর রবুবিয়্যাতের অধীন সবকিছুই সৃষ্ট। অতএব আরশ সৃষ্ট।","আর আল্লাহ সর্বোচ্চ বলেছেন:","“আর তিনিই আসমানসমূহ ও পৃথিবী ছয় দিনে সৃষ্টি করেছেন, এবং তাঁর আরশ ছিল পানির ওপর।”","[সূরা হূদ ১১:৭]","এখানে ‘পানি’ বলতে সমুদ্রের পানি উদ্দেশ্য নয়; বরং আল্লাহ সর্বোচ্চের বর্ণনা অনুযায়ী তা হলো আরশের নিচে থাকা পানি।"],"e":["Allah Most High said:","“And He is the Lord of the Mighty Throne.”","[Sūrat al-Tawbah 9:129]","Allah Most High described the Throne as something over which He exercises Lordship, and everything subject to His Lordship is created. Therefore, the Throne is created.","And Allah Most High said:","“And He is the One who created the heavens and the earth in six days, and His Throne was upon the water.”","[Sūrat Hūd 11:7]","What is meant by the water is not the water of the seas; rather, it is water beneath the Throne, as stated by Allah Most High."]},"n472":{"a":["قال الله تعالى:","﴿وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ﴾","[التوبة: ١٢٩]","وقال تعالى:","﴿وَالْمَلَكُ عَلَى أَرْجَائِهَا وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍ ثَمَانِيَةٌ﴾","[الحاقة: ١٧]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আর তিনিই মহান আরশের রব।”","[সূরা আত-তাওবাহ ৯:১২৯]","আর আল্লাহ সর্বোচ্চ বলেছেন:","“ফেরেশতাগণ তার প্রান্তসমূহে থাকবে, এবং সেদিন তাদের ওপর আপনার রবের আরশ বহন করবে আটজন।”","[সূরা আল-হাক্কাহ ৬৯:১৭]"],"e":["Allah Most High said:","“And He is the Lord of the Mighty Throne.”","[Sūrat al-Tawbah 9:129]","And Allah Most High said:","“The angels will be on its edges, and on that Day eight will bear the Throne of your Lord above them.”","[Sūrat al-Ḥāqqah 69:17]"]},"e2.127":{"a":["قال الله تعالى:","﴿وَمَا قَدَرُوا اللهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ﴾","[الزمر: ٦٧]","وقال تعالى:","﴿يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَاوَاتُ﴾","[إبراهيم: ٤٨]","فهل العرش يدخل فيما يُقبض ويُطوى ويُبدل أو لا؟","فيرى شيخ الإسلام ابن تيمية رحمه الله تعالى أنه من المخلوقات التي لا تُعدم ولا تفنى بالكلية، كالجنة والنار والعرش وغير ذلك."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“তারা আল্লাহকে তাঁর যথাযথ মর্যাদায় মূল্যায়ন করেনি। কিয়ামতের দিন সমগ্র পৃথিবী তাঁর মুঠোয় থাকবে এবং আসমানসমূহ তাঁর ডান হাতে গুটানো থাকবে।”","[সূরা আয-যুমার ৩৯:৬৭]","আর আল্লাহ সর্বোচ্চ বলেছেন:","“যেদিন পৃথিবী পরিবর্তিত হয়ে অন্য পৃথিবীতে পরিণত হবে, এবং আসমানসমূহও।”","[সূরা ইবরাহীম ১৪:৪৮]","আরশ কি সেইসব জিনিসের অন্তর্ভুক্ত যেগুলো মুঠোয় নেওয়া, গুটানো ও পরিবর্তিত করা হবে, নাকি নয়?","পাণ্ডুলিপিতে বলা হয়েছে যে শাইখুল ইসলাম ইবন তাইমিয়্যাহ (রহিমাহুল্লাহ) এটিকে এমন সৃষ্ট জিনিসসমূহের অন্তর্ভুক্ত মনে করেছেন যেগুলো সম্পূর্ণভাবে বিলীন বা অস্তিত্বহীন হবে না—যেমন জান্নাত, জাহান্নাম, আরশ এবং অনুরূপ অন্যান্য সৃষ্ট জিনিস।"],"e":["Allah Most High said:","“They did not appraise Allah with the appraisal due to Him. The earth altogether will be in His grasp on the Day of Resurrection, and the heavens will be folded in His Right Hand.”","[Sūrat al-Zumar 39:67]","And Allah Most High said:","“On the Day when the earth will be changed to another earth, and the heavens as well.”","[Sūrat Ibrāhīm 14:48]","Does the Throne fall under that which will be grasped, folded, and changed, or not?","The manuscript states that Shaykh al-Islām Ibn Taymiyyah may Allah have mercy on him regarded it as one of the created things that will not be annihilated or cease to exist completely, like Paradise, the Fire, the Throne, and other such created things."]},"n499":{"a":["قال الله تعالى:","﴿وَمَا جَعَلْنَا أَصْحَابَ النَّارِ إِلَّا مَلَائِكَةً وَمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَةً لِلَّذِينَ كَفَرُوا … وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ وَمَا هِيَ إِلَّا ذِكْرَى لِلْبَشَرِ﴾","[المدثر: ٣١]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আমি জাহান্নামের প্রহরী হিসেবে কেবল ফেরেশতাদেরই নিযুক্ত করেছি, আর তাদের সংখ্যা আমি কাফিরদের জন্য কেবল পরীক্ষা হিসেবে নির্ধারণ করেছি … এবং আপনার রবের বাহিনী সম্পর্কে তিনি ছাড়া কেউ জানে না। এটি তো মানবজাতির জন্য কেবল একটি উপদেশ।”","[সূরা আল-মুদ্দাসসির ৭৪:৩১]"],"e":["Allah Most High said:","“We have appointed only angels as keepers of the Fire, and We have made their number only as a trial for those who disbelieve … and none knows the armies of your Lord except Him. It is nothing but a reminder for mankind.”","[Sūrat al-Muddaththir 74:31]"]},"n511":{"a":["قال الله تعالى:","﴿إِلَّا تَنْصُرُوهُ فَقَدْ نَصَرَهُ اللهُ إِذْ أَخْرَجَهُ الَّذِينَ كَفَرُوا ثَانِيَ اثْنَيْنِ إِذْ هُمَا فِي الْغَارِ إِذْ يَقُولُ لِصَاحِبِهِ لَا تَحْزَنْ إِنَّ اللهَ مَعَنَا فَأَنْزَلَ اللهُ سَكِينَتَهُ عَلَيْهِ وَأَيَّدَهُ بِجُنُودٍ لَمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ الَّذِينَ كَفَرُوا السُّفْلَى وَكَلِمَةُ اللهِ هِيَ الْعُلْيَا وَاللهُ عَزِيزٌ حَكِيمٌ﴾","[التوبة: ٤٠]","فيه إعلام من الله أصحاب رسول الله ﷺ بأنكم إذا لم تنصروه فالله ناصره ومعينه على عدوه، كما نصره آنفاً.","وقوله:","﴿إِذْ أَخْرَجَهُ الَّذِينَ كَفَرُوا﴾","وهم قريش، أخرجوه من وطنه وداره.","وقوله:","﴿ثَانِيَ اثْنَيْنِ﴾","أخرجوا النبي ﷺ وهو أحد الاثنين، أي: واحد من الاثنين، كما تقول العرب:","ثالث ثلاثة، أي: أحد الثلاثة، ورابع أربعة، أي: أحد الأربعة.","وهما رسول الله ﷺ وأبو بكر رضي الله عنه؛ لأنهما كانا قد خرجا هاربين من قريش إذ هموا بقتل رسول الله ﷺ، واختفيا في الغار الذي في الجبل الذي يقال له ثور.","وقوله:","﴿فَأَنْزَلَ اللهُ سَكِينَتَهُ عَلَيْهِ﴾","أي: على رسوله ﷺ.","وقوله:","﴿وَأَيَّدَهُ بِجُنُودٍ لَمْ تَرَوْهَا﴾","أي: قواه وحفظه من أعدائه بجنود، وهم الملائكة، لم تروها، فكانوا محافظين من في الغار، والكفار قد قربوا منهم إلا أنهم لم يستطيعوا أن يقفوا عليهما."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“তোমরা যদি তাকে সাহায্য না করো, তবে আল্লাহ ইতোমধ্যেই তাকে সাহায্য করেছেন, যখন কাফিররা তাকে বের করে দিয়েছিল—দুজনের একজন হিসেবে—যখন তারা উভয়ে গুহায় ছিল এবং তিনি তাঁর সঙ্গীকে বলেছিলেন: ‘দুঃখ করো না; নিশ্চয়ই আল্লাহ আমাদের সঙ্গে আছেন।’","এরপর আল্লাহ তাঁর ওপর প্রশান্তি নাযিল করলেন, তাকে এমন বাহিনী দিয়ে সাহায্য করলেন যা তোমরা দেখনি, কাফিরদের বাণীকে সর্বনিম্ন করলেন এবং আল্লাহর বাণীই সর্বোচ্চ। আর আল্লাহ মহাপরাক্রমশালী, প্রজ্ঞাময়।”","[সূরা আত-তাওবাহ ৯:৪০]","এই আয়াত রাসূলুল্লাহ ﷺ-এর সাহাবিদের জানায় যে তারা যদি তাঁকে সাহায্য না-ও করত, তবু আল্লাহ তাঁর শত্রুদের বিরুদ্ধে তাঁর সাহায্যকারী ও সহায় ছিলেন—যেমন তিনি পূর্বেও তাঁকে সাহায্য করেছিলেন।","তাঁর বাণী:","“যখন কাফিররা তাকে বের করে দিয়েছিল”","এর দ্বারা কুরাইশকে বোঝানো হয়েছে, যারা তাঁকে তাঁর মাতৃভূমি ও ঘর থেকে বের করে দিয়েছিল।","তাঁর বাণী:","“দুজনের একজন”","অর্থাৎ নবী ﷺ ছিলেন সেই দুজনের একজন। এটি আরবিতে “তিনজনের তৃতীয়” বলার মতো—অর্থাৎ তিনজনের একজন; অথবা “চারজনের চতুর্থ”—অর্থাৎ চারজনের একজন।","সেই দুজন ছিলেন রাসূলুল্লাহ ﷺ এবং আবূ বকর (রাদিয়াল্লাহু আনহু)। কুরাইশ যখন রাসূলুল্লাহ ﷺ-কে হত্যা করার ইচ্ছা করেছিল, তখন তারা কুরাইশ থেকে পালিয়ে বের হন এবং সাওর নামে পরিচিত পাহাড়ের গুহায় আশ্রয় নেন।","তাঁর বাণী:","“এরপর আল্লাহ তাঁর ওপর প্রশান্তি নাযিল করলেন”","অর্থাৎ তাঁর রাসূল ﷺ-এর ওপর।","তাঁর বাণী:","“এবং তাকে এমন বাহিনী দিয়ে সাহায্য করলেন যা তোমরা দেখনি”","অর্থাৎ আল্লাহ তাঁর শত্রুদের বিরুদ্ধে তাঁকে এমন বাহিনী—অর্থাৎ ফেরেশতাদের—দিয়ে শক্তিশালী ও সুরক্ষিত করেছিলেন, যাদের মানুষ দেখেনি।","তারা গুহায় অবস্থানকারীদের পাহারা দিয়েছিল। কাফিররা তাদের অত্যন্ত কাছে এসে গেলেও তাদের দুজনকে খুঁজে পায়নি।"],"e":["Allah Most High said:","“If you do not support him, Allah has already supported him when those who disbelieved drove him out as one of two, when the two were in the cave and he said to his companion: ‘Do not grieve; indeed, Allah is with us.’","Then Allah sent down His tranquility upon him, supported him with forces you did not see, made the word of those who disbelieved the lowest, while the Word of Allah is supreme. And Allah is Mighty, All-Wise.”","[Sūrat al-Tawbah 9:40]","This verse informs the Companions of the Messenger of Allah ﷺ that even if they did not support him, Allah was his Supporter and Helper against his enemies, just as He had previously supported him.","His statement:","“When those who disbelieved drove him out”","refers to Quraysh, who drove him from his homeland and his home.","His statement:","“One of two”","means that the Prophet ﷺ was one of the two. This is like the Arabic expression “the third of three,” meaning one of three, or “the fourth of four,” meaning one of four.","The two were the Messenger of Allah ﷺ and Abū Bakr may Allah be pleased with him. They had left while fleeing from Quraysh when Quraysh intended to kill the Messenger of Allah ﷺ, and they hid in the cave in the mountain known as Thawr.","His statement:","“Then Allah sent down His tranquility upon him”","means: upon His Messenger ﷺ.","His statement:","“And supported him with forces you did not see”","means that Allah strengthened and protected him from his enemies with forces — namely the angels — whom the people did not see.","They guarded those who were in the cave. Although the disbelievers came very near them, they were unable to discover the two of them."]},"e2.138":{"a":["قال الله تعالى:","﴿إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُمْ بِأَلْفٍ مِنَ الْمَلَائِكَةِ مُرْدِفِينَ﴾","[الأنفال: ٩]","وقال تعالى:","﴿وَلَقَدْ نَصَرَكُمُ اللهُ بِبَدْرٍ وَأَنْتُمْ أَذِلَّةٌ فَاتَّقُوا اللهَ لَعَلَّكُمْ تَشْكُرُونَ ۝ إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَنْ يَكْفِيَكُمْ أَنْ يُمِدَّكُمْ رَبُّكُمْ بِثَلَاثَةِ آلَافٍ مِنَ الْمَلَائِكَةِ مُنْزَلِينَ﴾","[آل عمران: ١٢٣–١٢٤]","وقال تعالى:","﴿بَلَى إِنْ تَصْبِرُوا وَتَتَّقُوا وَيَأْتُوكُمْ مِنْ فَوْرِهِمْ هَذَا يُمْدِدْكُمْ رَبُّكُمْ بِخَمْسَةِ آلَافٍ مِنَ الْمَلَائِكَةِ مُسَوِّمِينَ﴾","[آل عمران: ١٢٥]","هذه الآيات كلها نزلت في غزوة بدر، فأول ما نزلت الملائكة كان عددهم ألفاً، ثم صاروا ثلاثة آلاف، ثم صاروا خمسة آلاف.","قوله:","﴿وَأَنْتُمْ أَذِلَّةٌ﴾","جمع ذليل، أراد به قلة العدد، فكان عدد المسلمين ثلاثمائة وثلاثة عشر رجلاً، وعدد المشركين نحو تسعمائة إلى الألف.","قال ابن عباس رضي الله عنهما:","«لم تقاتل الملائكة في المعركة إلا يوم بدر، وفيما سوى ذلك يشهدون القتال ولا يقاتلون، إنما يكونون عدداً ومدداً».","وقوله:","﴿مِنْ فَوْرِهِمْ﴾","أي: من ساعتهم ووقتهم بلا إبطاء."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“যখন তোমরা তোমাদের রবের কাছে সাহায্য প্রার্থনা করেছিলে, তখন তিনি তোমাদের ডাকে সাড়া দিয়েছিলেন: ‘নিশ্চয়ই আমি ধারাবাহিকভাবে আগমনকারী এক হাজার ফেরেশতা দিয়ে তোমাদের শক্তিশালী করব।’”","[সূরা আল-আনফাল ৮:৯]","আর আল্লাহ সর্বোচ্চ বলেছেন:","“আল্লাহ অবশ্যই বদরে তোমাদের বিজয় দিয়েছিলেন যখন তোমরা দুর্বল ছিলে; অতএব আল্লাহকে ভয় করো, যাতে তোমরা কৃতজ্ঞ হও। যখন আপনি মুমিনদের বলেছিলেন: ‘তোমাদের জন্য কি যথেষ্ট নয় যে তোমাদের রব নাযিলকৃত তিন হাজার ফেরেশতা দিয়ে তোমাদের শক্তিশালী করবেন?’”","[আলে ইমরান ৩:১২৩–১২৪]","আর আল্লাহ সর্বোচ্চ বলেছেন:","“হ্যাঁ! যদি তোমরা ধৈর্য ধারণ করো ও তাকওয়া অবলম্বন করো এবং তারা হঠাৎ তোমাদের ওপর এসে পড়ে, তবে তোমাদের রব চিহ্নিত পাঁচ হাজার ফেরেশতা দিয়ে তোমাদের শক্তিশালী করবেন।”","[আলে ইমরান ৩:১২৫]","এই সব আয়াত বদরের যুদ্ধ সম্পর্কে নাযিল হয়েছে।","প্রথমে ফেরেশতার সংখ্যা এক হাজার, পরে তিন হাজার, এরপর পাঁচ হাজার উল্লেখ করা হয়েছে।","“যখন তোমরা দুর্বল ছিলে”","এখানে তাদের সংখ্যার স্বল্পতাকে বোঝানো হয়েছে। মুসলিমদের সংখ্যা ছিল তিনশ তেরো জন, আর মুশরিকদের সংখ্যা ছিল প্রায় নয়শ থেকে এক হাজার।","ইবন আব্বাস (রাদিয়াল্লাহু আনহুমা) বলেছেন:","“ফেরেশতারা বদরের দিন ছাড়া কোনো যুদ্ধে যুদ্ধ করেননি। অন্য যুদ্ধে তারা যুদ্ধক্ষেত্রে উপস্থিত থাকতেন, কিন্তু যুদ্ধ করতেন না; বরং শক্তিবৃদ্ধি ও সহায়তা হিসেবে উপস্থিত থাকতেন।”","“তাৎক্ষণিকভাবে”","অর্থাৎ সেই মুহূর্ত ও সেই সময় থেকেই, কোনো বিলম্ব ছাড়াই।"],"e":["Allah Most High said:","“When you called upon your Lord for help, He answered you: ‘Indeed, I will reinforce you with one thousand angels following one another.’”","[Sūrat al-Anfāl 8:9]","And Allah Most High said:","“Allah certainly gave you victory at Badr while you were weak, so fear Allah that you may be grateful. When you said to the believers: ‘Is it not enough for you that your Lord should reinforce you with three thousand angels sent down?’”","[Āl ʿImrān 3:123–124]","And Allah Most High said:","“Yes! If you remain patient and mindful of Allah, and they come upon you suddenly, your Lord will reinforce you with five thousand angels, clearly marked.”","[Āl ʿImrān 3:125]","All of these verses were revealed concerning the Battle of Badr.","The first number of angels mentioned was one thousand, then three thousand, and then five thousand.","The words:","“While you were weak”","refer here to their small number. The Muslims numbered three hundred and thirteen men, whereas the polytheists numbered approximately nine hundred to one thousand.","“The angels did not fight in battle except on the Day of Badr. In battles other than that, they attended the fighting but did not fight; rather, they were present as reinforcement and support.”","The words:","“immediately”","mean: from that very hour and moment, without delay."]},"e2.140":{"a":["قال الله تعالى:","﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَةَ اللهِ عَلَيْكُمْ إِذْ جَاءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَمْ تَرَوْهَا وَكَانَ اللهُ بِمَا تَعْمَلُونَ بَصِيرًا﴾","[الأحزاب: ٩]","قوله:","﴿جَاءَتْكُمْ جُنُودٌ﴾","أي: الأحزاب من الكفار والمشركين، فأقبل أبو سفيان بقريش ومن معه من الناس حتى نزلوا بعقوة رسول الله ﷺ، وأقبل عيينة بن حصن ومن تبعه من الناس حتى نزلوا.","وقوله:","﴿فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا﴾","فبعث الله عليهم الرعب والريح، ويقال: كلما أوقدوا ناراً أطفأتها.","وقوله:","﴿وَجُنُودًا لَمْ تَرَوْهَا﴾","هم الملائكة في أصح أقوال أهل العلم، إلا أنهم لم يقاتلوا؛ لأن الله كفى المؤمنين القتال."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“হে মুমিনগণ, তোমাদের ওপর আল্লাহর অনুগ্রহ স্মরণ করো, যখন বাহিনীসমূহ তোমাদের বিরুদ্ধে এসেছিল, তখন আমি তাদের বিরুদ্ধে এক প্রবল বাতাস এবং এমন বাহিনী পাঠিয়েছিলাম যা তোমরা দেখনি। আর তোমরা যা করো আল্লাহ তা সর্বদ্রষ্টা।”","[সূরা আল-আহযাব ৩৩:৯]","“বাহিনীসমূহ তোমাদের বিরুদ্ধে এসেছিল”","এর দ্বারা কাফির ও মুশরিকদের সম্মিলিত বাহিনী বোঝানো হয়েছে। আবূ সুফিয়ান কুরাইশ ও তাদের সঙ্গীদের নিয়ে এসে রাসূলুল্লাহ ﷺ-এর নিকটে অবস্থান নেয়, আর উয়াইনাহ ইবন হিসন তার অনুসারীদের নিয়ে এসে একইভাবে সেখানে অবস্থান করে।","“আমি তাদের বিরুদ্ধে এক বাতাস এবং বাহিনী পাঠিয়েছিলাম”","অর্থাৎ আল্লাহ তাদের বিরুদ্ধে ভয় ও বাতাস পাঠিয়েছিলেন। বলা হয়, তারা যখনই আগুন জ্বালাত, বাতাস তা নিভিয়ে দিত।","“এমন বাহিনী যা তোমরা দেখনি”","পাণ্ডুলিপিতে আলেমদের উল্লেখিত শক্তিশালী মত অনুযায়ী এর দ্বারা ফেরেশতাদের বোঝানো হয়েছে। তারা যুদ্ধ করেননি, কারণ আল্লাহ মুমিনদের যুদ্ধ করা থেকে রক্ষা করেছিলেন।"],"e":["Allah Most High said:","“O you who believe, remember Allah’s favor upon you when armies came against you, and We sent against them a wind and forces you did not see. And Allah is All-Seeing of what you do.”","[Sūrat al-Aḥzāb 33:9]","The words:","“Armies came against you”","refer to the confederate armies of the disbelievers and polytheists. Abū Sufyān came with Quraysh and those accompanying them until they encamped near the Messenger of Allah ﷺ, and ʿUyaynah ibn Ḥiṣn came with those who followed him and likewise encamped there.","The words:","“We sent against them a wind and forces”","mean that Allah sent fear and wind against them. It is said that whenever they kindled a fire, the wind extinguished it.","The words:","“Forces you did not see”","refer, according to the strongest view mentioned by the scholars in the manuscript, to the angels. They did not fight, because Allah spared the believers from having to fight."]},"n513":{"a":["كانت غزوة بني قريظة في السنة الخامسة من الهجرة عقب غزوة الأحزاب، وكان سببها نقض بني قريظة العهد الذي بينهم وبين النبي ﷺ وقت غزوة قريش وحلفائها المدينة، فأمر الله تعالى نبيه بالتوجه إليهم لقتالهم."],"b":["বানূ কুরাইযার বিরুদ্ধে অভিযান হিজরতের পঞ্চম বছরে, আহযাবের যুদ্ধের পরপরই সংঘটিত হয়।","এর কারণ ছিল—কুরাইশ ও তাদের মিত্ররা মদিনায় আক্রমণ করার সময় বানূ কুরাইযা তাদের ও নবী ﷺ-এর মধ্যকার চুক্তি ভঙ্গ করেছিল। তাই আল্লাহ সর্বোচ্চ তাঁর নবী ﷺ-কে তাদের বিরুদ্ধে অগ্রসর হওয়ার নির্দেশ দেন।"],"e":["The campaign against Banū Qurayẓah took place in the fifth year after the Hijrah, immediately following the Battle of the Confederates.","Its cause was that Banū Qurayẓah broke the covenant between themselves and the Prophet ﷺ during the attack by Quraysh and its allies upon Madinah. Allah Most High therefore commanded His Prophet ﷺ to proceed against them."]},"e2.142":{"a":["قال الله تعالى:","﴿لَقَدْ نَصَرَكُمُ اللهُ فِي مَوَاطِنَ كَثِيرَةٍ وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنْكُمْ شَيْئًا وَضَاقَتْ عَلَيْكُمُ الْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُمْ مُدْبِرِينَ ۝ ثُمَّ أَنْزَلَ اللهُ سَكِينَتَهُ عَلَى رَسُولِهِ وَعَلَى الْمُؤْمِنِينَ وَأَنْزَلَ جُنُودًا لَمْ تَرَوْهَا وَعَذَّبَ الَّذِينَ كَفَرُوا وَذَلِكَ جَزَاءُ الْكَافِرِينَ﴾","[التوبة: ٢٥–٢٦]","كان عدد المسلمين في هذه الغزوة عشرة آلاف من المهاجرين والأنصار، وألفين من الطلقاء، وكان عدد المشركين أربعة آلاف من هوازن وثقيف.","قال سعيد بن جبير:","أمد الله تعالى نبيه بخمسة آلاف من الملائكة مسومين.","وفي الخبر أن رجلاً من بني نضر يقال له شجرة، قال للمؤمنين بعد القتال:","أين الخيل البلق والرجال الذين عليهم ثياب بيض؟ ما كنا نراكم فيهم إلا كهيئة الشامة، وما كنا قتلنا إلا بأيديهم.","فأخبروا بذلك النبي ﷺ فقال:","«تلك الملائكة».","ذكره البغوي في تفسيره."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আল্লাহ বহু স্থানে তোমাদের বিজয় দিয়েছেন, এবং হুনাইনের দিনও—যখন তোমাদের সংখ্যাধিক্য তোমাদের মুগ্ধ করেছিল, কিন্তু তা তোমাদের কোনো উপকার করেনি; আর পৃথিবী প্রশস্ত হওয়া সত্ত্বেও তোমাদের জন্য সংকীর্ণ হয়ে গিয়েছিল, তারপর তোমরা পিঠ ফিরিয়ে পালিয়েছিলে।","এরপর আল্লাহ তাঁর রাসূল ও মুমিনদের ওপর প্রশান্তি নাযিল করলেন এবং এমন বাহিনী নাযিল করলেন যা তোমরা দেখনি; আর তিনি কাফিরদের শাস্তি দিলেন। এটাই কাফিরদের প্রতিফল।”","[সূরা আত-তাওবাহ ৯:২৫–২৬]","এই যুদ্ধে মুসলিমদের সংখ্যা ছিল মুহাজির ও আনসারদের মধ্য থেকে দশ হাজার, সঙ্গে মক্কা বিজয়ের সময় সদ্য ক্ষমাপ্রাপ্তদের মধ্য থেকে আরও দুই হাজার।","মুশরিকদের সংখ্যা ছিল হাওয়াযিন ও সাকীফ থেকে চার হাজার।","সাঈদ ইবন জুবাইর বলেছেন:","“আল্লাহ সর্বোচ্চ তাঁর নবী ﷺ-কে পাঁচ হাজার চিহ্নিত ফেরেশতা দিয়ে শক্তিশালী করেছিলেন।”","বর্ণিত হয়েছে যে বানূ নাদর গোত্রের শাজারাহ নামে এক ব্যক্তি যুদ্ধের পর মুমিনদের বলেছিল:","“ছোপযুক্ত ঘোড়া আর সাদা পোশাক পরা লোকগুলো কোথায়? তাদের মাঝে তোমাদের আমরা প্রায় ছোট্ট দাগের মতোই দেখেছিলাম, আর যাদের আমরা হত্যা করেছিলাম তারা যেন কেবল তাদের হাতেই নিহত হয়েছিল।”","তারা বিষয়টি নবী ﷺ-কে জানালে তিনি বললেন:","“ওরা ছিল ফেরেশতা।”","আল-বাগাওয়ী তাঁর তাফসীরে এটি উল্লেখ করেছেন।"],"e":["Allah Most High said:","“Allah has certainly given you victory in many places, and on the Day of Ḥunayn, when your great numbers impressed you but benefited you nothing, and the earth, vast as it was, became constricted for you, then you turned away fleeing.","Then Allah sent down His tranquility upon His Messenger and upon the believers, and He sent down forces you did not see, and punished those who disbelieved. That is the recompense of the disbelievers.”","[Sūrat al-Tawbah 9:25–26]","The number of Muslims in this battle was ten thousand from among the Muhājirūn and Anṣār, together with two thousand of those who had recently been pardoned at the conquest of Makkah.","The polytheists numbered four thousand from Hawāzin and Thaqīf.","Saʿīd ibn Jubayr said:","“Allah Most High reinforced His Prophet ﷺ with five thousand marked angels.”","It is reported that a man from Banū Naḍr named Shajarah said to the believers after the battle:","“Where were the dappled horses and the men wearing white garments? We could hardly see you among them except like a small mark, and those whom we killed were killed only through their hands.”","They informed the Prophet ﷺ of this, and he said:","“Those were the angels.”","Al-Baghawī mentioned it in his Tafsīr."]},"n545":{"a":["قال الله تعالى:","﴿الَّذِينَ يَحْمِلُونَ الْعَرْشَ وَمَنْ حَوْلَهُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ﴾","[غافر: ٧]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“যারা আরশ বহন করে এবং যারা তার চারপাশে রয়েছে, তারা তাদের রবের প্রশংসাসহ তাসবীহ করে।”","[সূরা গাফির ৪০:৭]"],"e":["Allah Most High said:","“Those who carry the Throne and those around it glorify their Lord with praise.”","[Sūrat Ghāfir 40:7]"]},"n601":{"b":["٦٠١"],"e":["٦٠١"]},"n602":{"b":["٦٠٢"],"e":["٦٠٢"]},"n611":{"a":["قال الله تعالى:","﴿فَأَرْسَلْنَا إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا﴾","[مريم: ١٧]","والروح اسم من أسماء جبريل عليه السلام، مثل قوله تعالى:","﴿تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِمْ مِنْ كُلِّ أَمْرٍ﴾","[القدر: ٤]","قال ابن عباس رضي الله عنهما:","الروح هو جبريل."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“এরপর আমি তার কাছে আমার রূহকে পাঠালাম, আর সে তার সামনে এক সুগঠিত মানুষের আকৃতিতে প্রকাশ পেল।”","[সূরা মারইয়াম ১৯:১৭]","‘আর-রূহ’ জিবরীল (আলাইহিস সালাম)-এর নামসমূহের একটি; যেমন আল্লাহ সর্বোচ্চ বলেছেন:","“সে রাতে ফেরেশতাগণ ও রূহ তাদের রবের অনুমতিতে প্রত্যেক বিষয় নিয়ে অবতরণ করে।”","[সূরা আল-কদর ৯৭:৪]","ইবন আব্বাস (রাদিয়াল্লাহু আনহুমা) বলেছেন:","“আর-রূহ হলেন জিবরীল।”"],"e":["Allah Most High said:","“Then We sent to her Our Spirit, and he appeared before her as a well-proportioned man.”","[Sūrat Maryam 19:17]","“The Spirit” is one of the names of Jibrīl, peace be upon him,, as in the saying of Allah Most High:","“The angels and the Spirit descend therein by permission of their Lord with every matter.”","[Sūrat al-Qadr 97:4]","“The Spirit is Jibrīl.”"]},"n615":{"a":["قال الله تعالى:","﴿نَزَلَ بِهِ الرُّوحُ الْأَمِينُ﴾","[الشعراء: ١٩٣]","وقال تعالى:","﴿قُلْ نَزَّلَهُ رُوحُ الْقُدُسِ مِنْ رَبِّكَ بِالْحَقِّ﴾","[النحل: ١٠٢]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“বিশ্বস্ত রূহ তা নিয়ে অবতরণ করেছে।”","[সূরা আশ-শু‘আরা ২৬:১৯৩]","আর তিনি বলেছেন:","“বলুন: পবিত্র রূহ তা আপনার রবের পক্ষ থেকে সত্যসহ নাযিল করেছেন।”","[সূরা আন-নাহল ১৬:১০২]"],"e":["Allah Most High said:","“The Trustworthy Spirit brought it down.”","[Sūrat al-Shuʿarāʾ 26:193]","And He said:","“Say: The Holy Spirit has brought it down from your Lord in truth.”","[Sūrat al-Naḥl 16:102]"]},"n638":{"a":["قال الله تعالى:","﴿رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِنَ النَّاسِ فَمَنْ تَبِعَنِي فَإِنَّهُ مِنِّي وَمَنْ عَصَانِي فَإِنَّكَ غَفُورٌ رَحِيمٌ﴾","[إبراهيم: ٣٦]"],"b":["“হে আমার রব, নিশ্চয়ই তারা বহু মানুষকে পথভ্রষ্ট করেছে। অতএব যে আমার অনুসরণ করে, সে নিশ্চয়ই আমার অন্তর্ভুক্ত; আর যে আমার অবাধ্য হয়—তবে নিশ্চয়ই আপনি পরম ক্ষমাশীল, পরম দয়ালু।”","[সূরা ইবরাহীম ১৪:৩৬]"],"e":["“My Lord, indeed they have led many people astray. So whoever follows me is truly of me; and whoever disobeys me — then indeed You are Most Forgiving, Most Merciful.”","[Sūrat Ibrāhīm 14:36]"]},"n639":{"a":["قال الله تعالى:","﴿فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ﴾","[القيامة: ١٨]"],"b":["“অতএব আমি যখন তা তিলাওয়াত করি, তখন আপনি তার তিলাওয়াত অনুসরণ করুন।”","[সূরা আল-কিয়ামাহ ৭৫:১৮]"],"e":["“So when We have recited it, then follow its recitation.”","[Sūrat al-Qiyāmah 75:18]"]},"n640":{"a":["قال الله تعالى:","﴿مَنْ كَانَ عَدُوًّا لِلَّهِ وَمَلَائِكَتِهِ وَرُسُلِهِ وَجِبْرِيلَ وَمِيكَالَ فَإِنَّ اللهَ عَدُوٌّ لِلْكَافِرِينَ﴾","[البقرة: ٩٨]"],"b":["“যে আল্লাহ, তাঁর ফেরেশতাগণ, তাঁর রাসূলগণ, জিবরীল ও মীকাঈলের শত্রু হয়—তবে নিশ্চয়ই আল্লাহ কাফিরদের শত্রু।”","[সূরা আল-বাকারা ২:৯৮]"],"e":["“Whoever is an enemy to Allah, His angels, His messengers, Jibrīl, and Mīkāl — then indeed Allah is an enemy to the disbelievers.”","[Sūrat al-Baqarah 2:98]"]},"n645":{"a":["قال الله تعالى:","﴿بِأَيْدِي سَفَرَةٍ ۝ كِرَامٍ بَرَرَةٍ﴾","[عبس: ١٥–١٦]"],"b":["“সম্মানিত ও সৎ লেখকদের হাতে।”","[সূরা আবাসা ৮০:১৫–১৬]"],"e":["“In the hands of scribes, noble and righteous.”","[Sūrat ʿAbasa 80:15–16]"]},"n646":{"a":["قال الله تعالى:","﴿وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا حَتَّى إِذَا جَاءُوهَا وَفُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَامٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَالِدِينَ﴾","[الزمر: ٧٣]"],"b":["“যারা তাদের রবকে ভয় করত, তাদের দলবদ্ধভাবে জান্নাতের দিকে নিয়ে যাওয়া হবে। অবশেষে যখন তারা সেখানে পৌঁছাবে এবং তার দরজাসমূহ খুলে দেওয়া হবে, তখন তার প্রহরীরা তাদের বলবে: ‘তোমাদের ওপর শান্তি বর্ষিত হোক। তোমরা উত্তম কাজ করেছ; অতএব চিরকাল থাকার জন্য এতে প্রবেশ করো।’”","[সূরা আয-যুমার ৩৯:৭৩]"],"e":["“Those who feared their Lord will be led to Paradise in groups until, when they reach it and its gates are opened, its keepers will say to them: ‘Peace be upon you. You have done well, so enter it to remain forever.’”","[Sūrat al-Zumar 39:73]"]},"n648":{"a":["قال الله تعالى:","﴿وَنَادَوْا يَا مَالِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ قَالَ إِنَّكُمْ مَاكِثُونَ﴾","[الزخرف: ٧٧]","ومالك هو خازن جهنم.","وقال تعالى:","﴿عَلَيْهَا تِسْعَةَ عَشَرَ﴾","[المدثر: ٣٠]","لعل مالكاً هو رئيسهم أو هو أعظم، ولذا خُص بالذكر من بينهم."],"b":["“আর তারা ডাকবে: ‘হে মালিক, আপনার রব যেন আমাদের শেষ করে দেন!’ সে বলবে: ‘নিশ্চয়ই তোমরা এখানেই থাকবে।’”","[সূরা আয-যুখরুফ ৪৩:৭৭]","মালিক হলেন জাহান্নামের প্রহরী।","“এর ওপর রয়েছে উনিশজন।”","[সূরা আল-মুদ্দাসসির ৭৪:৩০]","সম্ভবত মালিক তাদের প্রধান অথবা তাদের মধ্যে সর্বশ্রেষ্ঠ; তাই তাঁকে বিশেষভাবে উল্লেখ করা হয়েছে।"],"e":["“And they will call: ‘O Mālik, let your Lord put an end to us!’ He will say: ‘Indeed, you will remain.’”","[Sūrat al-Zukhruf 43:77]","Mālik is the keeper of Hell.","“Over it are nineteen.”","[Sūrat al-Muddaththir 74:30]","Perhaps Mālik is their chief, or the greatest among them, and therefore he was singled out for mention."]},"n650":{"a":["قال الله تعالى:","﴿قُلْ يَتَوَفَّاكُمْ مَلَكُ الْمَوْتِ الَّذِي وُكِّلَ بِكُمْ ثُمَّ إِلَى رَبِّكُمْ تُرْجَعُونَ﴾","[السجدة: ١١]"],"b":["“বলুন: ‘তোমাদের জন্য নিযুক্ত মৃত্যুর ফেরেশতা তোমাদের রূহ কবজ করবে; এরপর তোমাদের রবের কাছেই তোমাদের ফিরিয়ে নেওয়া হবে।’”","[সূরা আস-সাজদাহ ৩২:১১]"],"e":["“Say: ‘The Angel of Death, who has been entrusted with you, will take your souls; then to your Lord you will be returned.’”","[Sūrat al-Sajdah 32:11]"]},"n651":{"a":["قال الله تعالى:","﴿وَكَتَبْنَا لَهُ فِي الْأَلْوَاحِ مِنْ كُلِّ شَيْءٍ مَوْعِظَةً وَتَفْصِيلًا لِكُلِّ شَيْءٍ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا بِأَحْسَنِهَا﴾","[الأعراف: ١٤٥]","وقال الله تعالى:","﴿إِنَّا أَنْزَلْنَا التَّوْرَاةَ فِيهَا هُدًى وَنُورٌ يَحْكُمُ بِهَا النَّبِيُّونَ الَّذِينَ أَسْلَمُوا لِلَّذِينَ هَادُوا وَالرَّبَّانِيُّونَ وَالْأَحْبَارُ بِمَا اسْتُحْفِظُوا مِنْ كِتَابِ اللهِ وَكَانُوا عَلَيْهِ شُهَدَاءَ﴾","[المائدة: ٤٤]"],"b":["“আর আমি তাঁর জন্য ফলকসমূহে সব বিষয়ে উপদেশ এবং সবকিছুর বিস্তারিত ব্যাখ্যা লিখে দিয়েছিলাম: ‘এগুলো দৃঢ়ভাবে গ্রহণ করো এবং তোমার জাতিকে এর সর্বোত্তম বিষয়গুলো অনুসরণ করতে নির্দেশ দাও।’”","[সূরা আল-আ‘রাফ ৭:১৪৫]","“নিশ্চয়ই আমি তাওরাত নাযিল করেছি, যাতে ছিল হিদায়াত ও আলো। আত্মসমর্পণকারী নবীগণ এর দ্বারা ইহুদিদের বিচার করতেন, আর রব্বানী আলেম ও ধর্মজ্ঞরাও—কারণ তাদের আল্লাহর কিতাব সংরক্ষণের দায়িত্ব দেওয়া হয়েছিল এবং তারা এর সাক্ষী ছিল।”","[সূরা আল-মায়িদাহ ৫:৪৪]"],"e":["“We wrote for him upon the Tablets an admonition concerning all things and a detailed explanation of all things: ‘Take them firmly and command your people to follow the best of them.’”","[Sūrat al-Aʿrāf 7:145]","“Indeed, We sent down the Torah, in which was guidance and light. The prophets who submitted judged by it for the Jews, as did the devoted scholars and rabbis, by that which they were entrusted to preserve of the Book of Allah, and they were witnesses to it.”","[Sūrat al-Māʾidah 5:44]"]},"n652":{"a":["قال الله تعالى:","﴿وَلَمَّا رَجَعَ مُوسَى إِلَى قَوْمِهِ غَضْبَانَ أَسِفًا قَالَ بِئْسَمَا خَلَفْتُمُونِي مِنْ بَعْدِي أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ وَأَلْقَى الْأَلْوَاحَ﴾","[الأعراف: ١٥٠]"],"b":["“আর যখন মূসা তাঁর জাতির কাছে ক্রুদ্ধ ও গভীর দুঃখিত অবস্থায় ফিরে এলেন, তিনি বললেন: ‘আমার অনুপস্থিতিতে তোমরা কত নিকৃষ্ট কাজ করেছ! তোমরা কি তোমাদের রবের আদেশের আগেই তাড়াহুড়ো করলে?’ আর তিনি ফলকসমূহ নিক্ষেপ করলেন।”","[সূরা আল-আ‘রাফ ৭:১৫০]"],"e":["“When Moses returned to his people angry and deeply grieved, he said: ‘How evil is what you did in my absence! Did you hasten the command of your Lord?’ And he threw down the Tablets.”","[Sūrat al-Aʿrāf 7:150]"]},"n653":{"a":["قال الله تعالى:","﴿قُلْ فَأْتُوا بِالتَّوْرَاةِ فَاتْلُوهَا إِنْ كُنْتُمْ صَادِقِينَ﴾","[آل عمران: ٩٣]"],"b":["“বলুন: ‘তবে তাওরাত নিয়ে আসো এবং তা পাঠ করো, যদি তোমরা সত্যবাদী হও।’”","[আলে ইমরান ৩:৯৩]"],"e":["“Say: ‘Then bring the Torah and recite it, if you are truthful.’”","[Āl ʿImrān 3:93]"]},"n656":{"a":["قال الله تعالى:","﴿وَأَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ مِنَ الْكِتَابِ وَمُهَيْمِنًا عَلَيْهِ﴾","[المائدة: ٤٨]"],"b":["“আমি আপনার প্রতি সত্যসহ কিতাব নাযিল করেছি, যা তার পূর্ববর্তী কিতাবসমূহের সত্যতা নিশ্চিতকারী এবং সেগুলোর ওপর রক্ষক।”","[সূরা আল-মায়িদাহ ৫:৪৮]"],"e":["“We have sent down to you the Book in truth, confirming the Scriptures that came before it and as a guardian over them.”","[Sūrat al-Māʾidah 5:48]"]},"e2.230":{"a":["قال الله تعالى:","﴿وَمَا يَأْتِيهِمْ مِنْ ذِكْرٍ مِنَ الرَّحْمَنِ مُحْدَثٍ إِلَّا كَانُوا عَنْهُ مُعْرِضِينَ﴾","[الشعراء: ٥]"],"b":["“আর-রহমানের পক্ষ থেকে তাদের কাছে নতুন কোনো স্মরণিকা এলেই তারা তা থেকে মুখ ফিরিয়ে নেয়।”","[সূরা আশ-শু‘আরা ২৬:৫]"],"e":["“No newly revealed reminder comes to them from the Most Merciful except that they turn away from it.”","[Sūrat al-Shuʿarāʾ 26:5]"]},"n662":{"a":["قال الله تعالى:","﴿إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ﴾","[القدر: ١]","وقال تعالى:","﴿شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ﴾","[البقرة: ١٨٥]","أي: إنه نزل في ليلة القدر من اللوح المحفوظ إلى السماء الدنيا، ثم أُنزل على النبي ﷺ على ما أراد الله إنزاله إليه.","جاء ذلك عن ابن عباس رضي الله عنهما من طرق كثيرة، ولم نجد له مخالفاً من أحد من الصحابة، ومن هذه الطرق:"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“নিশ্চয়ই আমি এটি কদরের রাতে নাযিল করেছি।”","[সূরা আল-কদর ৯৭:১]","আর তিনি বলেছেন:","“রমযান মাস—যে মাসে কুরআন নাযিল করা হয়েছে।”","[সূরা আল-বাকারা ২:১৮৫]","অর্থাৎ, এটি লাইলাতুল কদরে লাওহে মাহফূয থেকে নিকটতম আসমানে নাযিল হয়েছিল; এরপর আল্লাহ তাঁর প্রতি যা নাযিল করতে চেয়েছেন সে অনুযায়ী পর্যায়ক্রমে নবী ﷺ-এর প্রতি নাযিল করা হয়েছে।","ইবন আব্বাস (রাদিয়াল্লাহু আনহুমা) থেকে বহু সূত্রে এটি বর্ণিত হয়েছে, এবং পাণ্ডুলিপিতে বলা হয়েছে যে সাহাবিদের কারও থেকে এর বিরোধী কোনো বর্ণনা পাওয়া যায়নি। এসব সূত্রের মধ্যে নিম্নোক্তগুলো রয়েছে:"],"e":["Allah Most High said:","“Indeed, We sent it down on the Night of Decree.”","[Sūrat al-Qadr 97:1]","And He said:","“Ramaḍān is the month in which the Qurʾān was sent down.”","[Sūrat al-Baqarah 2:185]","That is, it descended on Laylat al-Qadr from the Preserved Tablet to the lowest heaven, and thereafter it was sent down to the Prophet ﷺ according to what Allah willed to reveal to him.","This has been reported from Ibn ʿAbbās may Allah be pleased with them through numerous routes, and the manuscript states that no opposing report from any of the Companions has been found. Among these routes are the following:"]},"n672":{"a":["قال الله تعالى:","﴿نَزَلَ بِهِ الرُّوحُ الْأَمِينُ ۝ عَلَى قَلْبِكَ لِتَكُونَ مِنَ الْمُنْذِرِينَ ۝ بِلِسَانٍ عَرَبِيٍّ مُبِينٍ﴾","[الشعراء: ١٩٣–١٩٥]","وقال تعالى:","﴿وَكَذَلِكَ أَوْحَيْنَا إِلَيْكَ قُرْآنًا عَرَبِيًّا لِتُنْذِرَ أُمَّ الْقُرَى وَمَنْ حَوْلَهَا﴾","[الشورى: ٧]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“বিশ্বস্ত রূহ তা আপনার অন্তরে নিয়ে নাযিল করেছে, যাতে আপনি সতর্ককারীদের অন্তর্ভুক্ত হন—সুস্পষ্ট আরবি ভাষায়।”","[সূরা আশ-শু‘আরা ২৬:১৯৩–১৯৫]","আর তিনি বলেছেন:","“এভাবেই আমি আপনার প্রতি আরবি কুরআন ওহী করেছি, যাতে আপনি নগরসমূহের জননী এবং তার আশপাশের লোকদের সতর্ক করতে পারেন।”","[সূরা আশ-শূরা ৪২:৭]"],"e":["Allah Most High said:","“The Trustworthy Spirit brought it down upon your heart so that you may be among the warners, in a clear Arabic tongue.”","[Sūrat al-Shuʿarāʾ 26:193–195]","And He said:","“And thus We have revealed to you an Arabic Qurʾān so that you may warn the Mother of Cities and those around it.”","[Sūrat al-Shūrā 42:7]"]},"e2.240":{"a":["قال الله تعالى:","﴿وَرُسُلًا قَدْ قَصَصْنَاهُمْ عَلَيْكَ مِنْ قَبْلُ وَرُسُلًا لَمْ نَقْصُصْهُمْ عَلَيْكَ وَكَلَّمَ اللهُ مُوسَى تَكْلِيمًا﴾","[النساء: ١٦٤]","وهذه تسمية الأنبياء الذين نُص على أسمائهم في القرآن، وهم:","آدم، وإدريس، ونوح، وهود، وصالح، وإبراهيم، ولوط، وإسماعيل، وإسحاق، ويعقوب، ويوسف، وأيوب، وشعيب، وموسى، وهارون، ويونس، وداود، وسليمان، وإلياس، واليسع، وزكريا، ويحيى، وعيسى، وسيدهم جميعاً محمد بن عبد الله، صلوات الله وسلامه عليهم أجمعين.","وأما ذو الكفل، فقال كثير من المفسرين: إنه أيضاً من الأنبياء. كذا ذكره ابن كثير في تفسيره.","وقوله:","﴿وَرُسُلًا لَمْ نَقْصُصْهُمْ عَلَيْكَ﴾","أي: خلقاً آخرين لم يُذكروا في القرآن."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আর এমন রাসূলদের কথা আমি ইতোমধ্যে আপনার কাছে বর্ণনা করেছি, এবং এমন রাসূলদের কথাও আছে যাদের কথা আমি আপনার কাছে বর্ণনা করিনি। আর আল্লাহ মূসার সঙ্গে সরাসরি কথা বলেছেন।”","[সূরা আন-নিসা ৪:১৬৪]","কুরআনে যেসব নবীর নাম স্পষ্টভাবে উল্লেখ করা হয়েছে তাঁরা হলেন:","আদম, ইদরীস, নূহ, হূদ, সালিহ, ইবরাহীম, লূত, ইসমাঈল, ইসহাক, ইয়াকূব, ইউসুফ, আইয়ূব, শু‘আইব, মূসা, হারূন, ইউনুস, দাউদ, সুলাইমান, ইলইয়াস, আল-ইয়াসা‘, যাকারিয়্যা, ইয়াহইয়া, ঈসা এবং তাঁদের সবার নেতা মুহাম্মাদ ইবন আবদুল্লাহ—তাঁদের সকলের ওপর আল্লাহর শান্তি ও বরকত বর্ষিত হোক।","যুল-কিফলের ব্যাপারে বহু মুফাসসির বলেছেন যে তিনিও নবীদের অন্তর্ভুক্ত ছিলেন। ইবন কাসীর তাঁর তাফসীরে এটি উল্লেখ করেছেন।","আর তাঁর বাণী:","“এবং এমন রাসূলদের কথাও আছে যাদের কথা আমি আপনার কাছে বর্ণনা করিনি”","অর্থাৎ আরও অনেকে ছিলেন যাদের কুরআনে উল্লেখ করা হয়নি।"],"e":["Allah Most High said:","“And messengers We have already related to you before, and messengers We have not related to you. And Allah spoke directly to Moses.”","[Sūrat al-Nisāʾ 4:164]","These are the prophets whose names are explicitly mentioned in the Qurʾān:","Adam, Idrīs, Nūḥ, Hūd, Ṣāliḥ, Abraham, Lot, Ishmael, Isaac, Jacob, Joseph, Job, Shuʿayb, Moses, Aaron, Jonah, David, Solomon, Elijah, Elisha, Zechariah, John, Jesus, and the leader of them all, Muḥammad ibn ʿAbdullāh — may Allah’s peace and blessings be upon them all.","As for Dhū al-Kifl, many commentators said that he too was among the prophets. Ibn Kathīr mentioned this in his Tafsīr.","Regarding His statement:","“And messengers We have not related to you,”","that is, others who were not mentioned in the Qurʾān."]},"n698":{"a":["قال الله تعالى:","﴿قُولُوا آمَنَّا بِاللهِ وَمَا أُنْزِلَ إِلَيْنَا وَمَا أُنْزِلَ إِلَى إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى وَمَا أُوتِيَ النَّبِيُّونَ مِنْ رَبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ﴾","[البقرة: ١٣٦]","الأنبياء عليهم الصلاة والسلام معصومون فيما يخبرون عن الله سبحانه وتعالى، وفي تبليغ رسالاته باتفاق الأمة؛ ولهذا وجب الإيمان بكل ما أتوا به.","وقال تعالى:","﴿آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ﴾","[البقرة: ٢٨٥]","والأنبياء معصومون من الإقرار على المعصية، وإن وقع منهم شيء سارعوا إلى التوبة ولا يصرون عليه.","ولذلك لم يذكر القرآن شيئًا من ذلك عن نبي من الأنبياء إلا مقرونًا بالتوبة والاستغفار، كقول آدم وزوجته:","﴿قَالَا رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ﴾","[الأعراف: ٢٣]","وقول نوح عليه السلام:","﴿قَالَ رَبِّ إِنِّي أَعُوذُ بِكَ أَنْ أَسْأَلَكَ مَا لَيْسَ لِي بِهِ عِلْمٌ وَإِلَّا تَغْفِرْ لِي وَتَرْحَمْنِي أَكُنْ مِنَ الْخَاسِرِينَ﴾","[هود: ٤٧]","وقول الخليل إبراهيم عليه السلام:","﴿وَالَّذِي أَطْمَعُ أَنْ يَغْفِرَ لِي خَطِيئَتِي يَوْمَ الدِّينِ﴾","[الشعراء: ٨٢]","وقول موسى عليه السلام:","﴿قَالَ رَبِّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي فَغَفَرَ لَهُ﴾","[القصص: ١٦]","وقوله:","﴿فَلَمَّا أَفَاقَ قَالَ سُبْحَانَكَ تُبْتُ إِلَيْكَ وَأَنَا أَوَّلُ الْمُؤْمِنِينَ﴾","[الأعراف: ١٤٣]","وقوله تعالى عن داود عليه السلام:","﴿وَظَنَّ دَاوُودُ أَنَّمَا فَتَنَّاهُ فَاسْتَغْفَرَ رَبَّهُ وَخَرَّ رَاكِعًا وَأَنَابَ﴾","[ص: ٢٤]","وقوله تعالى عن سليمان عليه السلام:","﴿قَالَ رَبِّ اغْفِرْ لِي وَهَبْ لِي مُلْكًا لَا يَنْبَغِي لِأَحَدٍ مِنْ بَعْدِي إِنَّكَ أَنْتَ الْوَهَّابُ﴾","[ص: ٣٥]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“বলুন: আমরা ঈমান এনেছি আল্লাহর প্রতি এবং যা আমাদের প্রতি নাযিল করা হয়েছে, আর যা ইবরাহীম, ইসমাঈল, ইসহাক, ইয়াকূব ও বংশধরদের প্রতি নাযিল করা হয়েছিল, আর যা মূসা ও ঈসাকে দেওয়া হয়েছিল এবং যা নবীগণকে তাদের রবের পক্ষ থেকে দেওয়া হয়েছিল। আমরা তাদের কারও মধ্যে কোনো পার্থক্য করি না, আর আমরা তাঁরই প্রতি আত্মসমর্পণকারী।”","[সূরা আল-বাকারা ২:১৩৬]","উম্মতের ঐকমত্য অনুযায়ী, নবীগণ—তাঁদের ওপর শান্তি ও বরকত বর্ষিত হোক—আল্লাহ মহিমান্বিত ও সর্বোচ্চের পক্ষ থেকে যা পৌঁছে দেন এবং তাঁর রিসালাত পৌঁছে দেওয়ার ক্ষেত্রে ভুল থেকে সুরক্ষিত। তাই তাঁরা যা নিয়ে এসেছেন তার সবকিছুর প্রতি ঈমান আনা আবশ্যক।","আল্লাহ সর্বোচ্চ বলেছেন:","“রাসূল তাঁর রবের পক্ষ থেকে তাঁর প্রতি যা নাযিল করা হয়েছে তাতে ঈমান এনেছেন, আর মুমিনরাও। প্রত্যেকেই ঈমান এনেছে আল্লাহ, তাঁর ফেরেশতাগণ, তাঁর কিতাবসমূহ এবং তাঁর রাসূলদের প্রতি। ‘আমরা তাঁর কোনো রাসূলের মধ্যে পার্থক্য করি না।’ আর তারা বলে: ‘আমরা শুনলাম এবং মান্য করলাম। হে আমাদের রব, আমরা আপনার ক্ষমা চাই; আর আপনার কাছেই চূড়ান্ত প্রত্যাবর্তন।’”","[সূরা আল-বাকারা ২:২৮৫]","নবীগণ গুনাহের ওপর অবিচল থাকা থেকে সুরক্ষিত। তাঁদের থেকে কিছু ঘটে গেলে তাঁরা দ্রুত তাওবা করেন এবং তাতে অবিচল থাকেন না।","এই কারণেই কুরআনে কোনো নবীর ব্যাপারে এ ধরনের কিছু উল্লেখ করা হলে তার সঙ্গে তাওবা ও ক্ষমা প্রার্থনাও উল্লেখ করা হয়েছে; যেমন আদম ও তাঁর স্ত্রীর বক্তব্য:","“তারা বলল: ‘হে আমাদের রব, আমরা নিজেদের ওপর যুলুম করেছি। আপনি যদি আমাদের ক্ষমা না করেন এবং আমাদের প্রতি দয়া না করেন, তবে অবশ্যই আমরা ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হব।’”","[সূরা আল-আ‘রাফ ৭:২৩]","আর নূহ (আলাইহিস সালাম)-এর বক্তব্য:","“তিনি বললেন: ‘হে আমার রব, যে বিষয়ে আমার কোনো জ্ঞান নেই সে বিষয়ে আপনার কাছে প্রার্থনা করা থেকে আমি আপনার আশ্রয় চাই। আপনি যদি আমাকে ক্ষমা না করেন এবং আমার প্রতি দয়া না করেন, তবে আমি ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হব।’”","[সূরা হূদ ১১:৪৭]","আর আল-খলীল ইবরাহীম (আলাইহিস সালাম)-এর বক্তব্য:","“আর তিনিই সেই সত্তা, যাঁর কাছে আমি আশা করি যে বিচার দিবসে তিনি আমার ত্রুটিসমূহ ক্ষমা করবেন।”","[সূরা আশ-শু‘আরা ২৬:৮২]","আর মূসা (আলাইহিস সালাম)-এর বক্তব্য:","“তিনি বললেন: ‘হে আমার রব, নিশ্চয়ই আমি নিজের ওপর যুলুম করেছি; অতএব আমাকে ক্ষমা করুন।’ তখন তিনি তাঁকে ক্ষমা করলেন।”","[সূরা আল-কাসাস ২৮:১৬]","আর মূসা (আলাইহিস সালাম) সম্পর্কে তাঁর বাণী:","“যখন তিনি চেতনা ফিরে পেলেন, তিনি বললেন: ‘আপনি পবিত্র! আমি আপনার কাছে তাওবা করছি এবং আমি মুমিনদের মধ্যে প্রথম।’”","[সূরা আল-আ‘রাফ ৭:১৪৩]","আর দাউদ (আলাইহিস সালাম) সম্পর্কে আল্লাহ সর্বোচ্চ বলেছেন:","“দাউদ বুঝতে পারলেন যে আমি তাঁকে পরীক্ষা করেছি; তখন তিনি তাঁর রবের কাছে ক্ষমা প্রার্থনা করলেন, রুকুতে লুটিয়ে পড়লেন এবং তাওবায় ফিরে এলেন।”","[সূরা সাদ ৩৮:২৪]","আর সুলাইমান (আলাইহিস সালাম) সম্পর্কে আল্লাহ সর্বোচ্চ বলেছেন:","“তিনি বললেন: ‘হে আমার রব, আমাকে ক্ষমা করুন এবং আমাকে এমন এক রাজত্ব দান করুন যা আমার পরে আর কারও জন্য উপযুক্ত হবে না। নিশ্চয়ই আপনিই মহাদাতা।’”","[সূরা সাদ ৩৮:৩৫]"],"e":["Allah Most High said:","“Say: We believe in Allah and what has been sent down to us, and what was sent down to Abraham, Ishmael, Isaac, Jacob, and the Tribes, and what was given to Moses and Jesus, and what was given to the prophets from their Lord. We make no distinction between any of them, and to Him we submit.”","[Sūrat al-Baqarah 2:136]","The prophets, peace and blessings be upon them, are protected from error in what they convey concerning Allah, Glorified and Exalted, and in delivering His messages, by the agreement of the Ummah. Therefore, it is obligatory to believe everything they brought.","Allah Most High said:","“The Messenger believes in what has been sent down to him from his Lord, and so do the believers. Each believes in Allah, His angels, His Books, and His messengers. ‘We make no distinction between any of His messengers.’ And they say: ‘We hear and we obey. We seek Your forgiveness, our Lord, and to You is the final return.’”","[Sūrat al-Baqarah 2:285]","The prophets are protected from persisting in disobedience. If something occurs from them, they hasten to repentance and do not persist in it.","For this reason, the Qurʾān does not mention anything of this nature concerning a prophet except together with repentance and seeking forgiveness, such as the statement of Adam and his wife:","“They said: ‘Our Lord, we have wronged ourselves. If You do not forgive us and have mercy upon us, we will surely be among the losers.’”","[Sūrat al-Aʿrāf 7:23]","And the statement of Noah, peace be upon him:","“He said: ‘My Lord, I seek refuge with You from asking You about that of which I have no knowledge. Unless You forgive me and have mercy upon me, I will be among the losers.’”","[Sūrat Hūd 11:47]","And the statement of Abraham, al-Khalīl peace be upon him:","“And He is the One whom I hope will forgive my shortcomings on the Day of Judgment.”","[Sūrat al-Shuʿarāʾ 26:82]","And the statement of Moses, peace be upon him:","“He said: ‘My Lord, indeed I have wronged myself, so forgive me.’ And He forgave him.”","[Sūrat al-Qaṣaṣ 28:16]","And His statement concerning Moses, peace be upon him:","“When he recovered, he said: ‘Glory be to You! I repent to You, and I am the first of the believers.’”","[Sūrat al-Aʿrāf 7:143]","And Allah Most High said concerning David peace be upon him:","“David realized that We had tested him, so he sought forgiveness from his Lord",", fell down bowing, and turned in repentance.”","[Sūrat Ṣād 38:24]","And Allah Most High said concerning Solomon peace be upon him:","“He said: ‘My Lord, forgive me and grant me a kingdom that will belong to no one after me. Indeed, You are the Bestower.’”","[Sūrat Ṣād 38:35]"]},"n702":{"a":["قال الله تعالى:","﴿يَا أَهْلَ الْكِتَابِ لَا تَغْلُوا فِي دِينِكُمْ وَلَا تَقُولُوا عَلَى اللهِ إِلَّا الْحَقَّ إِنَّمَا الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ رَسُولُ اللهِ وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ وَرُوحٌ مِنْهُ فَآمِنُوا بِاللهِ وَرُسُلِهِ وَلَا تَقُولُوا ثَلَاثَةٌ انْتَهُوا خَيْرًا لَكُمْ إِنَّمَا اللهُ إِلَهٌ وَاحِدٌ سُبْحَانَهُ أَنْ يَكُونَ لَهُ وَلَدٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللهِ وَكِيلًا﴾","[النساء: ١٧١]","قوله تعالى:","﴿وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ﴾","أي: إنما هو عبد من عباد الله، ومخلوق من خلقه، قال له:","كن،","فكان، ورسول من رسله."],"b":["“হে কিতাবধারীরা, তোমরা তোমাদের দ্বীনে বাড়াবাড়ি করো না এবং আল্লাহ সম্পর্কে সত্য ছাড়া কিছু বলো না। মারইয়ামের পুত্র মসীহ ঈসা কেবল আল্লাহর একজন রাসূল, তাঁর সেই কালিমা যা তিনি মারইয়ামের প্রতি নিক্ষেপ করেছিলেন এবং তাঁর পক্ষ থেকে এক রূহ। অতএব আল্লাহ ও তাঁর রাসূলদের প্রতি ঈমান আনো এবং বলো না, ‘তিন।’ বিরত হও—এটাই তোমাদের জন্য উত্তম। আল্লাহ তো একমাত্র এক ইলাহ। তাঁর সন্তান থাকার বিষয় থেকে তিনি পবিত্র। আসমানসমূহে যা আছে এবং পৃথিবীতে যা আছে সবই তাঁর। আর কর্মবিধায়ক হিসেবে আল্লাহই যথেষ্ট।”","[সূরা আন-নিসা ৪:১৭১]","তাঁর বাণী:","“তাঁর সেই কালিমা যা তিনি মারইয়ামের প্রতি নিক্ষেপ করেছিলেন”","এর অর্থ হলো—ঈসা আল্লাহর বান্দাদের একজন বান্দা এবং তাঁর সৃষ্টির একজন সৃষ্টি মাত্র। আল্লাহ তাঁকে বলেছিলেন:","“হও,”","আর তিনি হয়ে গেলেন। তিনি তাঁর রাসূলদের একজনও।"],"e":["“O People of the Scripture, do not go to extremes in your religion, and do not say about Allah except the truth. The Messiah, Jesus son of Mary, was only a messenger of Allah, His Word which He cast to Mary, and a spirit from Him. So believe in Allah and His messengers, and do not say, ‘Three.’ Desist—it is better for you. Allah is only One Allah. Glorified is He above having a son. To Him belongs whatever is in the heavens and whatever is on the earth, and Allah is sufficient as Disposer of affairs.”","[Sūrat al-Nisāʾ 4:171]","His statement:","“His Word which He cast to Mary”","means that Jesus is only a servant among the servants of Allah and a created being from His creation. Allah said to him:","“Be,”","and he was. He is also one of His messengers."]},"n730":{"a":["قال الله تعالى:","﴿وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ بَشِيرًا وَنَذِيرًا﴾","[سبأ: ٢٨]","وقال الله تعالى:","﴿قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللهِ إِلَيْكُمْ جَمِيعًا﴾","[الأعراف: ١٥٨]","وقال تعالى:","﴿يَا أَيُّهَا النَّاسُ قَدْ جَاءَكُمْ بُرْهَانٌ مِنْ رَبِّكُمْ وَأَنْزَلْنَا إِلَيْكُمْ نُورًا مُبِينًا﴾","[النساء: ١٧٤]","وغيرها من الآيات، وهي كثيرة جدًا."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আমি আপনাকে সমগ্র মানবজাতির জন্যই সুসংবাদদাতা ও সতর্ককারী হিসেবে প্রেরণ করেছি।”","[সূরা সাবা ৩৪:২৮]","আর আল্লাহ সর্বোচ্চ বলেছেন:","“বলুন: হে মানবজাতি, নিশ্চয়ই আমি তোমাদের সকলের প্রতি আল্লাহর রাসূল।”","[সূরা আল-আ‘রাফ ৭:১৫৮]","আর তিনি বলেছেন:","“হে মানবজাতি, তোমাদের রবের পক্ষ থেকে তোমাদের কাছে এক সুস্পষ্ট প্রমাণ এসেছে, আর আমি তোমাদের প্রতি এক স্পষ্ট আলো নাযিল করেছি।”","[সূরা আন-নিসা ৪:১৭৪]","এ বিষয়ে আরও বহু আয়াত রয়েছে।"],"e":["Allah Most High said:","“We have not sent you except to all mankind, as a bearer of glad tidings and a warner.”","[Sūrat Sabaʾ 34:28]","And Allah Most High said:","“Say: O mankind, indeed I am the Messenger of Allah to you all.”","[Sūrat al-Aʿrāf 7:158]","And He said:","“O mankind, there has come to you a proof from your Lord, and We have sent down to you a clear light.”","[Sūrat al-Nisāʾ 4:174]","There are many other verses concerning this as well."]},"n735":{"a":["قال الله تعالى:","﴿وَإِذْ صَرَفْنَا إِلَيْكَ نَفَرًا مِنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْآنَ فَلَمَّا حَضَرُوهُ قَالُوا أَنْصِتُوا فَلَمَّا قُضِيَ وَلَّوْا إِلَى قَوْمِهِمْ مُنْذِرِينَ ۝ قَالُوا يَا قَوْمَنَا إِنَّا سَمِعْنَا كِتَابًا أُنْزِلَ مِنْ بَعْدِ مُوسَى مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ يَهْدِي إِلَى الْحَقِّ وَإِلَى طَرِيقٍ مُسْتَقِيمٍ ۝ يَا قَوْمَنَا أَجِيبُوا دَاعِيَ اللهِ وَآمِنُوا بِهِ يَغْفِرْ لَكُمْ مِنْ ذُنُوبِكُمْ وَيُجِرْكُمْ مِنْ عَذَابٍ أَلِيمٍ﴾","[الأحقاف: ٢٩–٣١]","وقال تعالى:","﴿قُلْ أُوحِيَ إِلَيَّ أَنَّهُ اسْتَمَعَ نَفَرٌ مِنَ الْجِنِّ فَقَالُوا إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا﴾","[الجن: ١]","وقال عز وجل:","﴿يَا مَعْشَرَ الْجِنِّ وَالْإِنْسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِنْكُمْ يَقُصُّونَ عَلَيْكُمْ آيَاتِي وَيُنْذِرُونَكُمْ لِقَاءَ يَوْمِكُمْ هَذَا قَالُوا شَهِدْنَا عَلَى أَنْفُسِنَا وَغَرَّتْهُمُ الْحَيَاةُ الدُّنْيَا وَشَهِدُوا عَلَى أَنْفُسِهِمْ أَنَّهُمْ كَانُوا كَافِرِينَ﴾","[الأنعام: ١٣٠]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আর যখন আমি জিনদের একটি দলকে আপনার দিকে ফিরিয়ে দিয়েছিলাম, যাতে তারা কুরআন শোনে। যখন তারা সেখানে উপস্থিত হলো, তারা বলল: ‘মনোযোগ দিয়ে শোনো।’ এরপর যখন তা শেষ হলো, তারা সতর্ককারী হয়ে নিজেদের জাতির কাছে ফিরে গেল।","তারা বলল: ‘হে আমাদের জাতি, আমরা মূসার পরে নাযিলকৃত একটি কিতাব শুনেছি, যা তার পূর্ববর্তী কিতাবসমূহের সত্যতা নিশ্চিত করে। এটি সত্য ও সরল পথের দিকে নির্দেশ করে।","হে আমাদের জাতি, আল্লাহর দিকে আহ্বানকারীর ডাকে সাড়া দাও এবং তার প্রতি ঈমান আনো। তিনি তোমাদের কিছু গুনাহ ক্ষমা করবেন এবং যন্ত্রণাদায়ক শাস্তি থেকে তোমাদের রক্ষা করবেন।’”","[সূরা আল-আহকাফ ৪৬:২৯–৩১]","আর তিনি বলেছেন:","“বলুন: আমার প্রতি ওহী করা হয়েছে যে জিনদের একটি দল মনোযোগ দিয়ে শুনেছিল এবং বলেছিল: ‘নিশ্চয়ই আমরা এক বিস্ময়কর কুরআন শুনেছি।’”","[সূরা আল-জিন্ন ৭২:১]","আর তিনি মহাপরাক্রমশালী ও মহিমান্বিত বলেছেন:","“হে জিন ও মানুষের দল, তোমাদের মধ্য থেকে কি তোমাদের কাছে এমন রাসূল আসেনি যারা আমার আয়াতসমূহ তোমাদের কাছে বর্ণনা করত এবং তোমাদের এই দিনের সাক্ষাতের ব্যাপারে সতর্ক করত?","তারা বলবে: ‘আমরা নিজেদের বিরুদ্ধে সাক্ষ্য দিচ্ছি।’","দুনিয়ার জীবন তাদের প্রতারিত করেছিল, আর তারা নিজেদের বিরুদ্ধে সাক্ষ্য দেবে যে তারা কাফির ছিল।”","[সূরা আল-আন‘আম ৬:১৩০]"],"e":["Allah Most High said:","“And when We directed to you a group of the jinn to listen to the Qurʾān, when they attended it they said: ‘Listen attentively.’ When it was concluded, they returned to their people as warners.","They said: ‘O our people, indeed we have heard a Book revealed after Moses, confirming what came before it. It guides to the truth and to a straight path.","O our people, respond to the caller of Allah and believe in him. He will forgive you some of your sins and protect you from a painful punishment.’”","[Sūrat al-Aḥqāf 46:29–31]","And He said:","“Say: It has been revealed to me that a group of the jinn listened and said: ‘Indeed, we have heard a wondrous Qurʾān.’”","[Sūrat al-Jinn 72:1]","And He, Mighty and Majestic, said:","“O company of jinn and mankind, did there not come to you messengers from among you, relating My verses to you and warning you of the meeting of this Day of yours?","They will say: ‘We testify against ourselves.’","The worldly life deceived them, and they will testify against themselves that they were disbelievers.”","[Sūrat al-Anʿām 6:130]"]},"n749":{"a":["قال الله تعالى:","﴿مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَكِنْ رَسُولَ اللهِ وَخَاتَمَ النَّبِيِّينَ وَكَانَ اللهُ بِكُلِّ شَيْءٍ عَلِيمًا﴾","[الأحزاب: ٤٠]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“মুহাম্মাদ তোমাদের পুরুষদের কারও পিতা নন; বরং তিনি আল্লাহর রাসূল এবং নবীদের সীলমোহর। আর আল্লাহ সবকিছু সম্পর্কে সর্বজ্ঞ।”","[সূরা আল-আহযাব ৩৩:৪০]"],"e":["Allah Most High said:","“Muḥammad is not the father of any of your men, but he is the Messenger of Allah and the Seal of the Prophets. And Allah is All-Knowing of everything.”","[Sūrat al-Aḥzāb 33:40]"]},"n778":{"a":["قال الله تعالى:","﴿سُبْحَانَ الَّذِي أَسْرَىٰ بِعَبْدِهِ لَيْلًا مِنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى الَّذِي بَارَكْنَا حَوْلَهُ لِنُرِيَهُ مِنْ آيَاتِنَا إِنَّهُ هُوَ السَّمِيعُ الْبَصِيرُ﴾","[الإسراء: ١]","قال الزهري:","أُسري برسول الله ﷺ إلى بيت المقدس قبل خروجه إلى المدينة بسنة.","هكذا ذكر موسى بن عقبة عن ابن شهاب، وهو قول عروة أيضًا.","دلائل النبوة للبيهقي (٢/٣٥٤–٣٥٥).","وهذا هو الصحيح، وكان الإسراء والمعراج في ليلة واحدة ومرة واحدة، بالروح والجسد، يقظة لا منامًا، على رأي جمهور العلماء.","قال القرطبي:","«وعليه يدل ظاهر الكتاب وصحيح الأخبار، ومبادرة قريش لإنكار ذلك وتكذيبه، ولو كان منامًا لما أنكروه، ولما افتتن به من افتتن؛ إذ كثيرًا ما يرى في المنام أمور عجيبة وأحوال هائلة، فلا يستبعد ذلك في النوم، وإنما يستبعد في اليقظة».","المفهم (١/٣٨٥).","فهذه الآية أصل في إثبات الإسراء، وأنه كان بقدرة الله تعالى، لإراءة نبيه ﷺ من آياته.","واحتجاج القرطبي مبناه أن إنكار قريش ووقوع الفتنة إنما يليق بخبر عن أمر وقع يقظة لا منامًا.","وفي الحديث الآتي تظهر الآيات البينات عمليًا: شق الصدر، والعروج، ولقاء الأنبياء، وفرض الصلاة، ثم تخفيفها إلى خمس مع بقاء أجر الخمسين."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“পবিত্র সেই সত্তা, যিনি তাঁর বান্দাকে রাতে আল-মাসজিদুল হারাম থেকে আল-মাসজিদুল আকসায় নিয়ে গিয়েছিলেন, যার চারপাশকে আমি বরকতময় করেছি, যাতে তাঁকে আমার কিছু নিদর্শন দেখাই। নিশ্চয়ই তিনিই সর্বশ্রোতা, সর্বদ্রষ্টা।”","[সূরা আল-ইসরা ১৭:১]","আয-যুহরী বলেছেন:","“রাসূলুল্লাহ ﷺ-কে মদিনায় গমনের এক বছর আগে রাত্রিকালীন সফরে বাইতুল মাকদিসে নিয়ে যাওয়া হয়েছিল।”","মূসা ইবন উকবাহ ইবন শিহাব থেকে এভাবেই বর্ণনা করেছেন এবং উরওয়ার মতও এটাই ছিল।","আল-বায়হাকীর ‘দালাইল আন-নুবুওয়াহ’ (২/৩৫৪–৩৫৫)।","পাণ্ডুলিপিতে বলা হয়েছে, এটাই সঠিক মত: ইসরা ও মি‘রাজ একই রাতে ও একবারই সংঘটিত হয়েছিল, দেহ ও রূহ উভয়সহ, জাগ্রত অবস্থায়—স্বপ্নে নয়—অধিকাংশ আলেমের মতে।","আল-কুরতুবী বলেছেন:","“কুরআনের প্রকাশ্য অর্থ এবং সহীহ বর্ণনাসমূহ এটাই নির্দেশ করে; একইভাবে কুরাইশের তাৎক্ষণিক অস্বীকার ও প্রত্যাখ্যানও এর প্রমাণ। যদি তা কেবল স্বপ্ন হতো, তবে তারা তা অস্বীকার করত না এবং যারা এর দ্বারা পরীক্ষিত হয়েছিল তারাও পরীক্ষিত হতো না; কারণ মানুষ স্বপ্নে প্রায়ই বিস্ময়কর ও ভয়াবহ বিষয় দেখে, আর ঘুমের মধ্যে এমন বিষয়কে অসম্ভব মনে করা হয় না। এগুলো কেবল জাগ্রত অবস্থায় ঘটলেই অস্বাভাবিক বলে বিবেচিত হয়।”","আল-মুফহিম (১/৩৮৫)।","এই আয়াত ইসরা সম্পর্কে একটি মৌলিক প্রমাণ এবং এটি আল্লাহ সর্বোচ্চের ক্ষমতায় সংঘটিত হয়েছিল, যাতে তিনি তাঁর নবী ﷺ-কে তাঁর কিছু নিদর্শন দেখান।","আল-কুরতুবীর যুক্তি এই সত্যের ওপর ভিত্তি করে যে কুরাইশের অস্বীকার এবং এর পরবর্তী পরীক্ষা কেবল জাগ্রত অবস্থায় সংঘটিত কোনো ঘটনার সংবাদ সম্পর্কে উপযুক্ত—কেবল স্বপ্নের ঘটনার ক্ষেত্রে নয়।","পরবর্তী হাদীসে এসব নিদর্শনের সুস্পষ্ট প্রকাশ রয়েছে: নবী ﷺ-এর বক্ষ বিদারণ, আসমানসমূহে আরোহণ, নবীদের সঙ্গে সাক্ষাৎ, সালাত ফরয হওয়া এবং পঞ্চাশের সওয়াব বজায় রেখে তা পাঁচ ওয়াক্তে কমিয়ে দেওয়া।"],"e":["Allah Most High said:","“Glory be to the One who took His servant by night from al-Masjid al-Ḥarām to al-Masjid al-Aqṣā, whose surroundings We have blessed, in order to show him some of Our signs. Indeed, He alone is the All-Hearing, All-Seeing.”","[Sūrat al-Isrāʾ 17:1]","Al-Zuhrī said:","“The Messenger of Allah ﷺ was taken on the Night Journey to Bayt al-Maqdis one year before his departure to Madinah.”","This is how Mūsā ibn ʿUqbah reported it from Ibn Shihāb, and it was also the view of ʿUrwah.","Dalāʾil al-Nubuwwah by al-Bayhaqī (2/354–355).","The manuscript states that this is the correct view: the Night Journey and Ascension occurred in a single night and on one occasion, with both body and soul, while awake rather than in a dream, according to the majority of scholars.","Al-Qurṭubī said:","“The apparent meaning of the Qurʾān and the authentic reports indicate this, as does Quraysh’s immediate denial and rejection of it. Had it merely been a dream, they would not have denied it, nor would those who were tested by it have been tested; for people frequently see astonishing and terrifying things in dreams, and such matters are not considered far-fetched during sleep. They are only considered extraordinary when occurring while awake.”","Al-Mufhim (1/385).","This verse is a foundational proof for the Night Journey and that it occurred by the power of Allah Most High, so that He might show His Prophet ﷺ some of His signs.","Al-Qurṭubī’s argument is based upon the fact that Quraysh’s denial and the trial that followed are fitting only for a report concerning an event that occurred while awake, not merely in a dream.","The following ḥadīth contains clear manifestations of these signs: the opening of the Prophet’s ﷺ chest, the ascent through the heavens, meeting the prophets, the prescription of prayer, and its reduction to five prayers while retaining the reward of fifty."]},"n780":{"a":["قال الله تعالى:","﴿قُلْ إِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ يُوحَىٰ إِلَيَّ أَنَّمَا إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾","[الكهف: ١١٠]","وقال تعالى:","﴿وَمَا جَعَلْنَا لِبَشَرٍ مِنْ قَبْلِكَ الْخُلْدَ أَفَإِنْ مِتَّ فَهُمُ الْخَالِدُونَ﴾","[الأنبياء: ٣٤]","وقال تعالى:","﴿وَقَالُوا مَالِ هَذَا الرَّسُولِ يَأْكُلُ الطَّعَامَ وَيَمْشِي فِي الْأَسْوَاقِ﴾","[الفرقان: ٧]","وقد ورد في الصحيحين مرفوعًا:","«إنما أنا بشر مثلكم، أنسى كما تنسون، فإذا نسيت فذكروني».","رواه البخاري (٤٠١)، ومسلم (٥٧٢)."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“বলুন: আমি তো তোমাদের মতোই একজন মানুষ; আমার প্রতি ওহী করা হয় যে তোমাদের ইলাহ একমাত্র এক ইলাহ।”","[সূরা আল-কাহফ ১৮:১১০]","আর আল্লাহ সর্বোচ্চ বলেছেন:","“আপনার পূর্বে কোনো মানুষকেই আমি অমরত্ব দিইনি। অতএব আপনি যদি মৃত্যুবরণ করেন, তবে কি তারা চিরকাল বেঁচে থাকবে?”","[সূরা আল-আম্বিয়া ২১:৩৪]","আর তিনি বলেছেন:","“তারা বলে: এই রাসূলের কী হলো যে তিনি খাবার খান এবং বাজারে চলাফেরা করেন?”","[সূরা আল-ফুরকান ২৫:৭]","নবী ﷺ থেকে সহীহভাবে আরও বর্ণিত হয়েছে:","“আমি তো তোমাদের মতোই একজন মানুষ। তোমরা যেমন ভুলে যাও, আমিও তেমনি ভুলে যাই; অতএব আমি ভুলে গেলে আমাকে স্মরণ করিয়ে দিও।”","আল-বুখারী (৪০১) ও মুসলিম (৫৭২) বর্ণনা করেছেন।"],"e":["Allah Most High said:","“Say: I am only a human being like you, to whom it has been revealed that your Allah is One Allah.”","[Sūrat al-Kahf 18:110]","And Allah Most High said:","“We did not grant immortality to any human being before you. So if you die, will they then live forever?”","[Sūrat al-Anbiyāʾ 21:34]","And He said:","“They say: What is the matter with this Messenger that he eats food and walks in the marketplaces?”","[Sūrat al-Furqān 25:7]","It is also authentically reported from the Prophet ﷺ:","“I am only a human being like you. I forget just as you forget, so when I forget, remind me.”","Narrated by al-Bukhārī (401) and Muslim (572)."]},"n793":{"a":["قال الله تعالى:","﴿الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ مِنْ قَبْلِهِ هُمْ بِهِ يُؤْمِنُونَ ۝ وَإِذَا يُتْلَى عَلَيْهِمْ قَالُوا آمَنَّا بِهِ إِنَّهُ الْحَقُّ مِنْ رَبِّنَا إِنَّا كُنَّا مِنْ قَبْلِهِ مُسْلِمِينَ ۝ أُولَئِكَ يُؤْتَوْنَ أَجْرَهُمْ مَرَّتَيْنِ بِمَا صَبَرُوا وَيَدْرَءُونَ بِالْحَسَنَةِ السَّيِّئَةَ وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ﴾","[القصص: ٥٢–٥٤]","نزلت هذه الآية في طائفة آمنوا بالنبي ﷺ، كعبد الله بن سلام من اليهود، وسلمان الفارسي من النصارى."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“যাদের আমি এর পূর্বে কিতাব দিয়েছিলাম তারা এতে ঈমান আনে। আর যখন এটি তাদের কাছে তিলাওয়াত করা হয়, তারা বলে: ‘আমরা এতে ঈমান এনেছি। নিশ্চয়ই এটি আমাদের রবের পক্ষ থেকে সত্য। নিশ্চয়ই আমরা এর পূর্বেও মুসলিম ছিলাম।’ তাদের ধৈর্যের কারণে তাদেরকে দুবার প্রতিদান দেওয়া হবে। তারা মন্দকে ভালো দিয়ে প্রতিহত করে এবং আমি তাদের যা রিযিক দিয়েছি তা থেকে ব্যয় করে।”","[সূরা আল-কাসাস ২৮:৫২–৫৪]","এই আয়াত এমন একদল লোক সম্পর্কে নাযিল হয়েছিল যারা নবী ﷺ-এর প্রতি ঈমান এনেছিল; যেমন ইহুদিদের মধ্য থেকে আবদুল্লাহ ইবন সালাম এবং খ্রিস্টানদের মধ্য থেকে সালমান আল-ফারিসী।"],"e":["Allah Most High said:","“Those to whom We gave the Scripture before it believe in it. When it is recited to them, they say: ‘We believe in it. Indeed, it is the truth from our Lord. Indeed, even before it we were Muslims.’ Those will be given their reward twice because of their patience. They repel evil with good and spend from what We have provided them.”","[Sūrat al-Qaṣaṣ 28:52–54]","This verse was revealed concerning a group who believed in the Prophet ﷺ, such as ʿAbdullāh ibn Salām from the Jews and Salmān al-Fārisī from the Christians."]},"n802":{"a":["قال الله تعالى:","﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾","[الكوثر: ١]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“নিশ্চয়ই আমি আপনাকে আল-কাওসার দান করেছি।”","[সূরা আল-কাওসার ১০৮:১]"],"e":["Allah Most High said:","“Indeed, We have granted you al-Kawthar.”","[Sūrat al-Kawthar 108:1]"]},"n889":{"a":["إن الله تبارك وتعالى وعد نبيه ﷺ بهذا المقام في قوله عز وجل:","﴿عَسَىٰ أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا﴾","[الإسراء: ٧٩]","قال أهل العلم:","«عسى من الله واجب»، لا على الشك والارتياب."],"b":["আল্লাহ বরকতময় ও সর্বোচ্চ তাঁর নবী ﷺ-কে এই মর্যাদার প্রতিশ্রুতি দিয়েছেন তাঁর মহাপরাক্রমশালী ও মহিমান্বিত বাণীতে:","“আশা করা যায়, আপনার রব আপনাকে এক প্রশংসিত মর্যাদায় প্রতিষ্ঠিত করবেন।”","[সূরা আল-ইসরা ১৭:৭৯]","জ্ঞানীগণ বলেছেন:","“আল্লাহর পক্ষ থেকে ‘আসা’—‘আশা করা যায়’—বলা হলে তা নিশ্চিততার অর্থ বহন করে,” সন্দেহ বা অনিশ্চয়তার অর্থ নয়।"],"e":["Allah, Blessed and Exalted, promised His Prophet ﷺ this station in His statement, Mighty and Majestic:","“It may be that your Lord will raise you to a Praised Station.”","[Sūrat al-Isrāʾ 17:79]","The people of knowledge said:","“ʿAsā—‘it may be’—when stated by Allah indicates certainty,” not doubt or uncertainty."]},"n959":{"a":["قال الله تعالى:","﴿وَنَحْشُرُهُمْ يَوْمَ الْقِيَامَةِ عَلَى وُجُوهِهِمْ عُمْيًا وَبُكْمًا وَصُمًّا مَأْوَاهُمْ جَهَنَّمُ كُلَّمَا خَبَتْ زِدْنَاهُمْ سَعِيرًا﴾","[الإسراء: ٩٧]","وقال تعالى:","﴿الَّذِينَ يُحْشَرُونَ عَلَى وُجُوهِهِمْ إِلَى جَهَنَّمَ أُولَئِكَ شَرٌّ مَكَانًا وَأَضَلُّ سَبِيلًا﴾","[الفرقان: ٣٤]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“কিয়ামতের দিন আমি তাদের মুখের ওপর ভর করে সমবেত করব—অন্ধ, বোবা ও বধির অবস্থায়। তাদের আশ্রয় হবে জাহান্নাম। যখনই তার আগুন স্তিমিত হবে, আমি তাদের জন্য জ্বলন্ত আগুন আরও বাড়িয়ে দেব।”","[সূরা আল-ইসরা ১৭:৯৭]","আর তিনি বলেছেন:","“যাদের মুখের ওপর ভর করে জাহান্নামের দিকে সমবেত করা হবে—তারাই অবস্থানের দিক থেকে সর্বনিকৃষ্ট এবং পথ থেকে সর্বাধিক বিচ্যুত।”","[সূরা আল-ফুরকান ২৫:৩৪]"],"e":["Allah Most High said:","“We will gather them on the Day of Resurrection upon their faces—blind, mute, and deaf. Their refuge will be Hell. Whenever it subsides, We will increase for them the blazing Fire.”","[Sūrat al-Isrāʾ 17:97]","And He said:","“Those who will be gathered upon their faces toward Hell—those are the worst in position and the farthest astray from the path.”","[Sūrat al-Furqān 25:34]"]},"n983":{"a":["قال الله تعالى:","﴿مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الْأَرْضِ وَلَا فِي أَنْفُسِكُمْ إِلَّا فِي كِتَابٍ مِنْ قَبْلِ أَنْ نَبْرَأَهَا إِنَّ ذَٰلِكَ عَلَى اللهِ يَسِيرٌ﴾","[الحديد: ٢٢]","وقال تعالى:","﴿سُنَّةَ اللهِ فِي الَّذِينَ خَلَوْا مِنْ قَبْلُ وَكَانَ أَمْرُ اللهِ قَدَرًا مَقْدُورًا﴾","[الأحزاب: ٣٨]","قال مالك بن أنس رحمه الله:","«ما أضل من كذب بالقدر! لو لم يكن عليهم فيه حجة إلا قوله تعالى:","﴿هُوَ الَّذِي خَلَقَكُمْ فَمِنْكُمْ كَافِرٌ وَمِنْكُمْ مُؤْمِنٌ﴾","[التغابن: ٢]","لكفى بها حجة»."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“পৃথিবীতে বা তোমাদের নিজেদের মধ্যে কোনো বিপদই ঘটে না, তবে তা সংঘটিত করার পূর্বেই একটি কিতাবে লেখা থাকে। নিশ্চয়ই এটি আল্লাহর জন্য সহজ।”","[সূরা আল-হাদীদ ৫৭:২২]","আর আল্লাহ সর্বোচ্চ বলেছেন:","“এটাই পূর্বে অতিবাহিতদের ব্যাপারে আল্লাহর প্রতিষ্ঠিত বিধান, আর আল্লাহর আদেশ পূর্বনির্ধারিত এক ফয়সালা।”","[সূরা আল-আহযাব ৩৩:৩৮]","মালিক ইবন আনাস (রহিমাহুল্লাহ) বলেছেন:","“যে কদর অস্বীকার করে তার চেয়ে অধিক পথভ্রষ্ট কেউ নেই। এ বিষয়ে তাদের বিরুদ্ধে যদি আল্লাহ সর্বোচ্চের এই বাণী ছাড়া আর কোনো দলিলও না থাকত:","‘তিনিই তোমাদের সৃষ্টি করেছেন; তারপর তোমাদের কেউ কাফির এবং কেউ মুমিন,’","[সূরা আত-তাগাবুন ৬৪:২]","তবুও এই একটি আয়াতই দলিল হিসেবে যথেষ্ট হতো।”"],"e":["Allah Most High said:","“No calamity befalls the earth or yourselves except that it is written in a Record before We bring it into existence. Indeed, that is easy for Allah.”","[Sūrat al-Ḥadīd 57:22]","And Allah Most High said:","“This is the established way of Allah concerning those who passed away before, and the command of Allah is a decree already determined.”","[Sūrat al-Aḥzāb 33:38]","Mālik ibn Anas, may Allah have mercy on him, said:","“No one is more astray than one who denies Divine Decree. Even if there were no proof against them concerning it other than the statement of Allah Most High:","‘He is the One who created you; yet some of you are disbelievers and some of you are believers,’","[Sūrat al-Taghābun 64:2]","that alone would be sufficient as proof.”"]},"n1020":{"a":["قال الله تعالى:","﴿وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ﴾","[الأعراف: ٣٤]","وقال تعالى:","﴿وَمَا يُعَمَّرُ مِنْ مُعَمَّرٍ وَلَا يُنْقَصُ مِنْ عُمُرِهِ إِلَّا فِي كِتَابٍ إِنَّ ذَٰلِكَ عَلَى اللهِ يَسِيرٌ﴾","[فاطر: ١١]","قال الزهري رحمه الله:","«فنرى أنه إذا حضر أجله، فلا يؤخر ساعة ولا يقدم، وما لم يحضر أجله فإن الله يؤخر ما شاء ويقدم ما شاء».","انظر: القدر للفريابي (٤٤٢)."],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“প্রত্যেক জাতির জন্য একটি নির্ধারিত সময় রয়েছে। তাদের সময় এসে গেলে তারা এক মুহূর্তও তা বিলম্বিত করতে পারে না এবং এগিয়েও আনতে পারে না।”","[সূরা আল-আ‘রাফ ৭:৩৪]","আর আল্লাহ সর্বোচ্চ বলেছেন:","“কোনো ব্যক্তিকে দীর্ঘ জীবন দেওয়া হয় না এবং তার জীবনকাল থেকে কিছু কমানোও হয় না—তবে তা একটি কিতাবে লেখা আছে। নিশ্চয়ই এটি আল্লাহর জন্য সহজ।”","[সূরা ফাতির ৩৫:১১]","আয-যুহরী (রহিমাহুল্লাহ) বলেছেন:","“আমাদের অভিমত হলো—কোনো ব্যক্তির নির্ধারিত সময় এসে গেলে তা এক ঘণ্টাও বিলম্বিত হয় না এবং এগিয়েও আসে না। আর যার নির্ধারিত সময় এখনো আসেনি, আল্লাহ যা চান বিলম্বিত করেন এবং যা চান এগিয়ে আনেন।”","দেখুন: আল-ফিরইয়াবীর ‘আল-কদর’ (৪৪২)।"],"e":["Allah Most High said:","“For every nation there is an appointed term. When their term comes, they can neither delay it for a moment nor bring it forward.”","[Sūrat al-Aʿrāf 7:34]","And Allah Most High said:","“No person is granted a long life, nor is anything diminished from his lifespan, except that it is in a Record. Indeed, that is easy for Allah.”","[Sūrat Fāṭir 35:11]","Al-Zuhrī, may Allah have mercy on him, said:","“We hold that once a person’s appointed term arrives, it is neither delayed by an hour nor brought forward. As for that whose appointed term has not yet arrived, Allah delays whatever He wills and brings forward whatever He wills.”","See: al-Qadar by al-Firyābī (442)."]},"n1034":{"a":["قال الله تعالى:","﴿وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِنَ الْجِنِّ وَالْإِنْسِ لَهُمْ قُلُوبٌ لَا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لَا يُبْصِرُونَ بِهَا وَلَهُمْ آذَانٌ لَا يَسْمَعُونَ بِهَا أُولَٰئِكَ كَالْأَنْعَامِ بَلْ هُمْ أَضَلُّ أُولَٰئِكَ هُمُ الْغَافِلُونَ﴾","[الأعراف: ١٧٩]","وقال تعالى:","﴿وَلَوْ شَاءَ رَبُّكَ لَجَعَلَ النَّاسَ أُمَّةً وَاحِدَةً وَلَا يَزَالُونَ مُخْتَلِفِينَ ۝ إِلَّا مَنْ رَحِمَ رَبُّكَ وَلِذَٰلِكَ خَلَقَهُمْ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ﴾","[هود: ١١٨–١١٩]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আমি অবশ্যই জাহান্নামের জন্য বহু জিন ও মানুষ সৃষ্টি করেছি। তাদের হৃদয় আছে, কিন্তু তা দিয়ে তারা বোঝে না; তাদের চোখ আছে, কিন্তু তা দিয়ে তারা দেখে না; তাদের কান আছে, কিন্তু তা দিয়ে তারা শোনে না। তারা গবাদিপশুর মতো—বরং আরও অধিক পথভ্রষ্ট। তারাই গাফিল।”","[সূরা আল-আ‘রাফ ৭:১৭৯]","আর আল্লাহ সর্বোচ্চ বলেছেন:","“আপনার রব ইচ্ছা করলে মানবজাতিকে এক উম্মাহ করতে পারতেন; কিন্তু তারা মতভেদ করতেই থাকবে—তবে তারা ছাড়া যাদের প্রতি আপনার রব দয়া করেছেন। আর এ জন্যই তিনি তাদের সৃষ্টি করেছেন। আর আপনার রবের বাণী পূর্ণ হয়েছে: ‘আমি অবশ্যই জাহান্নামকে জিন ও মানুষ উভয় দিয়ে পূর্ণ করব।’”","[সূরা হূদ ১১:১১৮–১১৯]"],"e":["Allah Most High said:","“We have certainly created for Hell many of the jinn and humankind. They have hearts with which they do not understand, eyes with which they do not see, and ears with which they do not hear. They are like livestock—rather, even more astray. Those are the heedless.”","[Sūrat al-Aʿrāf 7:179]","And Allah Most High said:","“Had your Lord willed, He could have made mankind one community, but they will not cease differing, except those upon whom your Lord has mercy. And for that He created them. The word of your Lord has been fulfilled: ‘I will surely fill Hell with jinn and mankind all together.’”","[Sūrat Hūd 11:118–119]"]},"n1036":{"a":["قال الله تعالى:","﴿أَوَمَنْ كَانَ مَيْتًا فَأَحْيَيْنَاهُ وَجَعَلْنَا لَهُ نُورًا يَمْشِي بِهِ فِي النَّاسِ كَمَنْ مَثَلُهُ فِي الظُّلُمَاتِ لَيْسَ بِخَارِجٍ مِنْهَا كَذَٰلِكَ زُيِّنَ لِلْكَافِرِينَ مَا كَانُوا يَعْمَلُونَ﴾","[الأنعام: ١٢٢]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“যে ব্যক্তি মৃত ছিল, পরে আমি তাকে জীবন দিয়েছি এবং তার জন্য এমন এক আলো করেছি যার সাহায্যে সে মানুষের মধ্যে চলাফেরা করে—সে কি তার মতো, যে অন্ধকারের মধ্যে রয়েছে এবং তা থেকে কখনো বের হতে পারে না? এভাবেই কাফিরদের কাছে তাদের কাজকে শোভন করে দেওয়া হয়েছে।”","[সূরা আল-আন‘আম ৬:১২২]"],"e":["Allah Most High said:","“Is one who was dead and We gave him life and made for him a light by which he walks among the people like one whose likeness is in darkness from which he can never emerge? Thus what the disbelievers used to do has been made appealing to them.”","[Sūrat al-Anʿām 6:122]"]},"n1037":{"a":["قال الله تعالى:","﴿وَأَمَّا الْغُلَامُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ فَخَشِينَا أَنْ يُرْهِقَهُمَا طُغْيَانًا وَكُفْرًا ۝ فَأَرَدْنَا أَنْ يُبْدِلَهُمَا رَبُّهُمَا خَيْرًا مِنْهُ زَكَاةً وَأَقْرَبَ رُحْمًا﴾","[الكهف: ٨٠–٨١]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আর বালকটির পিতা-মাতা ছিল মুমিন। তাই আমরা আশঙ্কা করলাম যে সে বিদ্রোহ ও কুফর দ্বারা তাদের বিপর্যস্ত করবে। তাই আমরা চাইলাম যে তাদের রব তার পরিবর্তে তাদেরকে এমন একজন দান করুন যে তার চেয়ে অধিক পবিত্র এবং দয়ার দিক থেকে অধিক নিকটবর্তী।”","[সূরা আল-কাহফ ১৮:৮০–৮১]"],"e":["Allah Most High said:","“As for the boy, his parents were believers, and we feared that he would overwhelm them with rebellion and disbelief. So we intended that their Lord replace him for them with one better than him in purity and nearer in mercy.”","[Sūrat al-Kahf 18:80–81]"]},"n1088":{"a":["قال الله تعالى:","﴿وَالَّذِينَ آمَنُوا وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُمْ بِإِيمَانٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَا أَلَتْنَاهُمْ مِنْ عَمَلِهِمْ مِنْ شَيْءٍ ۚ كُلُّ امْرِئٍ بِمَا كَسَبَ رَهِينٌ﴾","[الطور: ٢١]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আর যারা ঈমান এনেছে এবং তাদের বংশধররা ঈমানের সঙ্গে তাদের অনুসরণ করেছে—আমি তাদের বংশধরদের তাদের সঙ্গে মিলিত করব এবং তাদের আমলের প্রতিদান থেকে কিছুই কমাব না। প্রত্যেক ব্যক্তি তার উপার্জনের জন্য বন্ধক রয়েছে।”","[সূরা আত-তূর ৫২:২১]"],"e":["Allah Most High said:","“Those who believed and whose descendants followed them in faith—We will join their descendants with them, and We will not diminish anything from the reward of their deeds. Every person is held in pledge for what he earned.”","[Sūrat al-Ṭūr 52:21]"]},"n1100":{"a":["قال الله تعالى:","﴿وَاللهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ﴾","[الصافات: ٩٦]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“আল্লাহ তোমাদের এবং তোমরা যা কর তা সৃষ্টি করেছেন।”","[সূরা আস-সাফফাত ৩৭:৯৬]"],"e":["Allah Most High said:","“Allah created you and what you do.”","[Sūrat al-Ṣāffāt 37:96]"]},"n1102":{"a":["قال الله تعالى:","﴿فَلَمَّا نَسُوا مَا ذُكِّرُوا بِهِ فَتَحْنَا عَلَيْهِمْ أَبْوَابَ كُلِّ شَيْءٍ حَتَّىٰ إِذَا فَرِحُوا بِمَا أُوتُوا أَخَذْنَاهُمْ بَغْتَةً فَإِذَا هُمْ مُبْلِسُونَ﴾","[الأنعام: ٤٤]","وقال تعالى:","﴿فَذَرْنِي وَمَنْ يُكَذِّبُ بِهَٰذَا الْحَدِيثِ سَنَسْتَدْرِجُهُمْ مِنْ حَيْثُ لَا يَعْلَمُونَ﴾","[القلم: ٤٤]"],"b":["আল্লাহ সর্বোচ্চ বলেছেন:","“অতঃপর যখন তারা যে বিষয়ে স্মরণ করিয়ে দেওয়া হয়েছিল তা ভুলে গেল, তখন আমি তাদের জন্য সবকিছুর দরজা খুলে দিলাম। অবশেষে যখন তারা যা পেয়েছিল তা নিয়ে উল্লসিত হলো, তখন আমি হঠাৎ তাদের পাকড়াও করলাম; ফলে সঙ্গে সঙ্গে তারা হতাশ হয়ে পড়ল।”","[সূরা আল-আন‘আম ৬:৪৪]","আর আল্লাহ সর্বোচ্চ বলেছেন:","“অতএব যে এই বাণীকে অস্বীকার করে তাকে আমার ওপর ছেড়ে দিন। আমি তাদের এমনভাবে ধীরে ধীরে পাকড়াওয়ের দিকে নিয়ে যাব যে তারা জানবেও না।”","[সূরা আল-কলম ৬৮:৪৪]"],"e":["Allah Most High said:","“So when they forgot what they had been reminded of, We opened for them the gates of everything, until, when they rejoiced in what they had been given, We seized them suddenly, and at once they were in despair.”","[Sūrat al-Anʿām 6:44]","And Allah Most High said:","“So leave Me with whoever denies this message. We will gradually draw them on from where they do not know.”","[Sūrat al-Qalam 68:44]"]}});